// Üretilen dosya: tool/ozgun/uret.py. Tarih · Fransız Devrimi, Napolyon ve 19. yüzyıl ulus devletleri (orta).
const ozHistory8Orta = <(String, String, List<String>, String)>[
  ('Köylülerin yol yapımı gibi işlerde yılın belirli günlerinde karşılıksız çalıştırılmasına Eski Rejim Fransa\'sında ne ad verilirdi?', 'Corvée (angarya)', ['Taille', 'Banalité (tekel hakkı)', 'Vingtième'], 'Corvée, kraliyet ya da senyör için zorunlu ve ücretsiz çalışma yükümlülüğüydü. Banalité senyörün değirmen, fırın gibi tesislerini kullanma zorunluluğudur.'),
  ('XVI. Louis\'nin İsviçre doğumlu maliye yöneticisi olan, 1781\'de kraliyet gelir-giderlerini kamuoyuna açıklayan ve Temmuz 1789\'da görevden alınması Paris\'i ayaklandıran kişi kimdir?', 'Jacques Necker', ['Anne Robert Jacques Turgot', 'Calonne', 'Colbert'], 'Necker\'in 1781\'deki Compte rendu\'su ve 11 Temmuz 1789\'da azledilmesi, Bastille baskınından önceki gerginliği tırmandıran olaylar arasındadır.'),
  ('Sieyès\'in broşüründeki \'Şimdiye kadar siyasi düzende neydi? Hiçbir şey. Ne istiyor? Bir şey olmak\' ifadeleri hangi talebi dile getirir?', 'Üçüncü zümrenin siyasi temsilde ağırlık kazanması', ['Mutlak monarşinin güçlendirilmesi', 'Kilisenin siyasette söz sahibi olması', 'Soyluların siyasi ayrıcalıklarının daha da artırılması'], 'Sieyès, üretenlerin çoğunluğunu oluşturan üçüncü zümrenin ulusun kendisi olduğunu ve siyasette buna uygun bir yer istediğini vurgular.'),
  ('1789\'da Etats Généraux seçimleri sırasında her seçim bölgesinden yakınma ve isteklerin yazıya geçirildiği defterlere ne ad verilir?', 'Şikâyet defterleri (cahiers de doléances)', ['Kırmızı Kitap', 'Muhtıra defterleri', 'Mavi defterler (bibliothèque bleue)'], 'Cahiers de doléances, üç zümrenin de krala iletmek istediği sorunları listeledi ve devrim öncesi kamuoyunu inceleyen tarihçiler için önemli bir kaynaktır.'),
  ('Top Oyunu Salonu Yemini\'nin siyasi açıdan en önemli anlamı aşağıdakilerden hangisidir?', 'Egemenliğin kraldan ulusun temsilcilerine geçtiğinin ilk kez iddia edilmesi', ['Kralın mutlak yetkisinin onaylanması', 'Kilisenin devlete bağlanması ve piskoposların memur sayılması', 'Fransa\'nın savaş ilan etmesi'], 'Temsilciler, kral dağıtsa bile anayasa yapacaklarını söyleyerek egemenliği kendilerine, yani ulusa ait saydılar.'),
  ('Haziran 1789\'da kendilerini Ulusal Meclis ilan eden üçüncü zümreye ilk katılan ayrıcalıklı zümre üyeleri çoğunlukla hangi kesimden gelmişti?', 'Köy rahipleri gibi alt din adamları', ['Saray soyluları', 'Piskoposlar, başrahipler ve kardinaller', 'Parlemento yargıçları'], 'Halka yakın, yoksul köy papazlarının bir bölümü üçüncü zümreye katıldı; birkaç gün sonra liberal soylular da onları izledi.'),
  ('Bastille baskınının 14 Temmuz 1789\'da gerçekleşmesinde aşağıdakilerden hangisi doğrudan etkili olmuştur?', 'Kralın Paris çevresine asker toplaması ve Necker\'i görevden alması', ['Kralın Varennes\'e kaçması', 'Avusturya\'nın Fransa\'ya savaş açması ve Paris\'e yürümesi', 'Kralın idam edilmesi'], 'Asker yığınağı ve Necker\'in azli Parislilerde meclisin dağıtılacağı korkusunu doğurdu; halk silah ve barut bulmak için Bastille\'e yürüdü.'),
  ('4 Ağustos kararlarının alınmasında Büyük Korku\'nun rolü en iyi hangi ifadeyle açıklanır?', 'Köylü isyanları meclisi kırsalı yatıştıracak hızlı reformlara zorladı', ['Büyük Korku kararlardan yıllar sonra yaşandı', 'Köylüler feodal hakların korunmasını istiyordu', 'Kararlar yalnız kentli işçileri ve zanaatkârları ilgilendiriyordu'], 'Meclis, mülkiyete yönelik saldırıların yayılmasından korkarak feodal düzenin kaldırılmasını ilan etti; böylece köylüleri yeniden düzene bağlamayı umdu.'),
  ('Ulusal Kurucu Meclis\'in 1789\'da Kilise topraklarını devletleştirmesindeki temel amaç neydi?', 'Devletin borçlarını ödemek için kaynak sağlamak', ['Kiliseyi güçlendirmek', 'Toprakları soylulara ve göçmenlere geri dağıtmak', 'Papalığa vergi ödemek'], 'Kilise mülkleri ulusun malı sayıldı ve satışa çıkarıldı. Bu mülklerin güvencesiyle assignat adı verilen kâğıtlar çıkarıldı.'),
  ('1790\'da kabul edilen Ruhban Sınıfının Sivil Anayasası din adamları için hangi düzenlemeyi getirmiştir?', 'Rahip ve piskoposların seçimle belirlenip devletten maaş alması', ['Din adamlarının her türlü vergiden ve yükümlülükten tamamen muaf tutulması', 'Piskoposların doğrudan papa tarafından atanması', 'Bütün manastırların korunması'], 'Sivil Anayasa, din adamlarını devlet memuru gibi seçimle göreve getirip maaşa bağladı ve onlardan anayasaya bağlılık yemini istedi.'),
  ('Fransa\'da 1791\'de lonca düzenini kaldıran kararın ardından işçilerin örgütlenip grev yapmasını da yasaklayan yasa hangisidir?', 'Le Chapelier Yasası', ['Azami Fiyat Yasası', 'Şüpheliler Yasası', 'Germinal Yasası'], 'Le Chapelier Yasası, ekonomik özgürlük adına hem loncaları hem de işçi birlikleri ile grevleri yasakladı; bu yasak 19. yüzyılda uzun süre etkili oldu.'),
  ('1791 Anayasası\'nda vergi ödeme düzeyine göre oy hakkı olan \'aktif yurttaşlar\' ile oy hakkı olmayan \'pasif yurttaşlar\' ayrımı neyi gösterir?', 'Seçme hakkının mülkiyete ve vergiye bağlandığını', ['Kadınlara oy hakkı tanındığını', 'Herkese eşit oy hakkı verilip mülkiyet şartının kaldırıldığını', 'Oy hakkının yalnız soylulara ait olduğunu'], 'Anayasa genel oy ilkesini benimsemedi; belli miktarda vergi ödeyen erkekler aktif yurttaş sayıldı. Bu, burjuva liberalizminin sınırını gösterir.'),
  ('Temmuz 1791\'de Paris\'te kralın tahttan indirilmesini isteyen dilekçeyi imzalamak için toplanan kalabalığa Ulusal Muhafız\'ın ateş açtığı olay hangisidir?', 'Champ de Mars Katliamı', ['Eylül Katliamları', 'Vendée Savaşı', 'Tuileries Sarayı Baskını'], '17 Temmuz 1791\'de Lafayette komutasındaki Ulusal Muhafız\'ın ateş açması, ılımlı devrimciler ile radikaller arasındaki kopuşu derinleştirdi.'),
  ('Ağustos 1791\'de Avusturya imparatoru ile Prusya kralının Fransız kralını destekleyebileceklerini açıkladıkları bildiri hangisidir?', 'Pillnitz Bildirisi', ['Brunswick Bildirisi', 'Berlin Kararnamesi', 'Karlsbad Kararları'], 'Pillnitz Bildirisi, öteki Avrupa hükümdarları da katılırsa Fransız monarşisine yardım edileceğini söylüyordu; devrimciler bunu bir tehdit olarak algıladı.'),
  ('Varennes\'den sonra anayasal monarşiyi korumak isteyen ılımlıların Jakoben Kulübü\'nden ayrılarak kurduğu grup hangisidir?', 'Feuillant\'lar', ['Dağlılar', 'Kordelyeler', 'Hébertçiler'], 'Feuillant Kulübü, kralı koruyarak devrimi durdurmayı amaçlayan ılımlılardan oluşuyordu; Barnave ve Lafayette bu çizgideydi.'),
  ('1792\'de Fransa\'nın savaşa girmesini en hararetli biçimde savunan, sonradan Konvansiyon\'da ılımlı kanadı oluşturacak grup hangisidir?', 'Jirondenler', ['Feuillant\'lar', 'Hébertçiler', 'Kraliyetçiler'], 'Brissot çevresindeki Jirondenler, savaşın devrimi yayacağını ve kralın ihanetini açığa çıkaracağını düşündüler. Robespierre ise savaşa karşı çıktı.'),
  ('XVI. Louis\'nin 1792\'de savaşı desteklemesinin ardındaki gizli hesap neydi?', 'Fransa\'nın yenilip yabancı orduların kendisini yeniden güçlendirmesi', ['Avusturya topraklarını savaşla Fransa\'ya katıp imparator olmak', 'Cumhuriyeti ilan etmek', 'İngiltere ile ittifak kurmak'], 'Kral ve kraliçe, Fransız ordusunun kötü durumunu bildikleri için bir yenilginin eski düzeni geri getireceğini umuyordu.'),
  ('Temmuz 1792\'de Prusya-Avusturya ordusunun komutanı adına yayımlanan ve krala zarar gelirse Paris\'in yerle bir edileceğini söyleyen bildiri hangisidir?', 'Brunswick Bildirisi', ['Pillnitz Bildirisi', 'Verona Bildirisi', 'Fontainebleau Bildirisi'], 'Brunswick Dükü\'nün bildirisi Parislileri korkutmak yerine öfkelendirdi ve 10 Ağustos ayaklanmasını hızlandırdı.'),
  ('10 Ağustos 1792\'de Paris halkı ve federelerin Tuileries Sarayı\'nı basmasının doğrudan sonucu hangisidir?', 'Monarşinin askıya alınması', ['Kralın yeniden mutlak yetki kazanması', 'Avusturya ile barış imzalanması', 'Napolyon\'un iktidara gelmesi'], 'Saray basıldı, İsviçre Muhafızları öldürüldü; Yasama Meclisi kralın yetkilerini askıya aldı ve yeni bir meclis için genel oyla seçim kararı verdi.'),
  ('Ulusal Konvansiyon\'un seçimi önceki meclislerin seçiminden hangi bakımdan ayrılır?', 'Erkekler için mülkiyet şartı olmadan oy hakkı tanınması', ['Kadınların da oy kullanması', 'Yalnız soyluların oy kullanması', 'Üyelerin kral ve parlementolar tarafından atanması'], 'Aktif-pasif yurttaş ayrımı kaldırıldı ve yetişkin erkekler genel oyla seçime katıldı; ancak katılım düşük kaldı.'),
  ('XVI. Louis\'nin idam edilmesinin Avrupa\'daki doğrudan sonucu hangisidir?', 'İngiltere, Hollanda ve İspanya\'nın da Fransa\'ya karşı savaşa girmesi', ['Avrupa monarşilerinin Fransız Cumhuriyeti\'ni hemen tanıyıp elçi göndermesi', 'Avusturya\'nın Fransa ile ittifak kurması', 'Rusya\'nın devrimi desteklemesi'], 'Kralın idamı Avrupa sarayları için bir meydan okumaydı; 1793\'te Birinci Koalisyon genişledi ve Fransa birçok cephede savaşmak zorunda kaldı.'),
  ('Konvansiyon\'da ne Dağlılara ne de Jirondenlere bağlı olan ve oylarıyla dengeyi belirleyen büyük orta kesime ne ad verilirdi?', 'Ova', ['Dağ', 'Sol Kanat', 'Kordelyeler Kulübü'], 'Ova üyeleri çoğunluğu oluşturuyordu; önce Dağlıları destekleyip Terör\'e onay verdiler, sonra Thermidor\'da Robespierre\'e karşı döndüler.'),
  ('Haziran 1793\'te Jirondenlerin Konvansiyon\'dan tasfiye edilmesinde hangi güç belirleyici olmuştur?', 'Paris\'in sans-culotte\'ları ve Ulusal Muhafız birliklerinin meclisi kuşatması', ['Avusturya ordusunun Paris\'e girip Jiroden bakanları tutuklaması', 'Kralın Jirondenleri görevden alması', 'Napolyon\'un darbe yapması'], '31 Mayıs-2 Haziran 1793\'te silahlı Paris seksiyonları Konvansiyon\'u kuşatarak Jiroden liderlerin tutuklanmasını sağladı; Dağlılar iktidarı ele geçirdi.'),
  ('Jirondenlerin tasfiyesinin ardından Lyon, Marsilya ve Bordeaux gibi kentlerde Paris\'e karşı başlayan ayaklanmalara ne ad verilir?', 'Federalist ayaklanmalar', ['Chouan savaşları', 'Haziran Günleri', 'Fronde ayaklanmaları'], 'Taşra kentleri Paris\'in meclis üzerindeki baskısına karşı çıktı. Konvansiyon bu ayaklanmaları sert biçimde bastırdı; Lyon kuşatılıp cezalandırıldı.'),
  ('Ağustos 1793\'te Konvansiyon\'un ilan ettiği ve bütün bekâr erkekleri askere çağırırken kadınları, yaşlıları ve çocukları da savaş çabasına katan uygulama hangisidir?', 'Levée en masse', ['Kıta Ablukası ve Berlin Kararnamesi', 'Konkordato', 'Meşruiyet ilkesi'], '18-25 yaş arası bekâr erkekler askere alındı; ulusun bütün kaynakları savaşa yöneltildi. Bu uygulama modern kitle ordularının başlangıcı sayılır.'),
  ('Levée en masse uygulamasının askerlik tarihi açısından önemi nedir?', 'Paralı ve küçük ordular yerine ulusal kitle ordularının doğması', ['Orduların tümüyle soylu subaylardan ve paralı askerlerden oluşması', 'Savaşların yalnız denizde yapılması', 'Zorunlu askerliğin kaldırılması'], 'Fransa yüz binlerce kişilik ordular kurarak koalisyon ordularını sayıca aştı; bu model 19. yüzyılda diğer devletlerce de benimsendi.'),
  ('Eylül 1793\'te çıkarılan ve devrime düşman olduğundan kuşkulanılan kişilerin geniş tanımlarla tutuklanmasına imkân veren yasa hangisidir?', 'Şüpheliler Yasası', ['Le Chapelier Yasası', 'Germinal Yasası', 'Karlsbad Kararları'], 'Şüpheliler Yasası, göçmenlerin yakınlarından eski görevlilere kadar pek çok kişiyi kapsıyordu ve Terör döneminde hapishaneleri doldurdu.'),
  ('1793\'te Konvansiyon\'un ekmek ve diğer temel malların fiyatına ve ücretlere üst sınır koyan düzenlemesine ne ad verilir?', 'Genel Azami Fiyat (Maximum)', ['Assignat', 'Fizyokrasi (Physiocratie)', 'Ticaret serbestisi'], 'Sans-culotte\'ların baskısıyla çıkarılan Genel Maximum, savaş ve enflasyon koşullarında fiyatları denetlemeyi amaçladı; Thermidor\'dan sonra kaldırıldı.'),
  ('Kamu Selameti Komitesi\'nde orduların örgütlenmesini yönettiği için \'zaferin örgütleyicisi\' diye anılan üye kimdir?', 'Lazare Carnot', ['Louis Antoine de Saint-Just', 'Couthon', 'Barère'], 'Carnot, levée en masse ile toplanan orduların düzenlenmesinde ve 1794 zaferlerinde başlıca rolü oynadı.'),
  ('Marat\'yı öldüren Charlotte Corday\'in bu eylemdeki amacı neydi?', 'Jirondenlere yönelik baskıya son vermek ve iç savaşı durdurmak', ['Kralı tahta geri getirmek için Avusturya\'ya yardım etmek', 'Robespierre\'in iktidarını güçlendirip Jirondenleri tasfiye etmek', 'Napolyon\'un yükselişini engellemek'], 'Corday, Marat\'yı Jirondenlerin düşüşünden ve şiddetin tırmanmasından sorumlu tutuyordu; ancak cinayet Marat\'yı bir devrim şehidine dönüştürdü.'),
  ('Le Père Duchesne gazetesini çıkaran, Hristiyanlıktan arındırma kampanyasını savunan ve Mart 1794\'te taraftarlarıyla birlikte idam edilen aşırı radikal lider kimdir?', 'Jacques Hébert', ['Camille Desmoulins', 'Lazare Carnot', 'Joseph Fouché'], 'Robespierre önce sol kanattaki Hébertçileri, ardından ılımlı Dantoncuları tasfiye etti. Böylece Terör\'ün iki kanadına da son verildi.'),
  ('Olympe de Gouges\'un \'Kadın ve Kadın Yurttaş Hakları Bildirisi\', 1789 bildirisine yönelik hangi eleştiriyi dile getirir?', 'Evrensel haklar ilan edildiği hâlde kadınların siyasi haklardan dışlanmasını', ['Bildirinin kralın yetkilerini fazla kısıtlayıp monarşiyi zayıflatmasını', 'Bildirinin mülkiyet hakkını tanımamasını', 'Bildirinin dini özgürlüğü fazla genişletmesini'], 'De Gouges, \'kadın darağacına çıkma hakkına sahipse kürsüye çıkma hakkına da sahip olmalıdır\' diyerek kadınların eşit yurttaşlığını savundu.'),
  ('Robespierre\'in genç ve ateşli yandaşı olan, \'Kimse masum olarak hüküm süremez\' diyerek kralın idamını savunan ve 1794\'te Robespierre ile birlikte idam edilen devrimci kimdir?', 'Louis Antoine de Saint-Just', ['Camille Desmoulins', 'Jean-Baptiste Carrier', 'Paul François Jean Nicolas Barras'], 'Saint-Just, kralın varlığının kendisinin bir suç olduğunu söyleyerek yargılamaya kuramsal bir gerekçe getirdi; 28 Temmuz 1794\'te idam edildi.'),
  ('Ilımlı bir soylu olup devrimin ilk aylarında meclisin en etkili hatibi olan, ölümünden sonra kralla gizli yazışmaları ortaya çıkan kişi kimdir?', 'Mirabeau Kontu', ['Lafayette Markisi', 'Talleyrand', 'Barnave'], 'Mirabeau 1791\'de öldü ve Panthéon\'a gömüldü. Kralla gizli ilişkisi 1792 sonunda Tuileries\'deki belgelerle ortaya çıkınca naaşı 1794\'te Panthéon\'dan çıkarıldı.'),
  ('Fransız Devrim Takvimi\'nde bir yıl kaç aya bölünmüştü?', '12', ['10', '13', '9'], 'Devrim Takvimi\'nde her biri 30 günlük 12 ay ve yılın sonuna eklenen 5 ya da 6 tamamlayıcı gün vardı.'),
  ('Fransız Devrim Takvimi\'nde haftanın yerini alan on günlük dönemin adı nedir?', 'Dekad', ['Olimpiyat', 'Lüstrum', 'Fructidor'], 'Her ay üç dekada bölündü ve onuncu gün (décadi) dinlenme günü oldu. Böylece pazar gününün dinî anlamı ortadan kaldırılmak istendi.'),
  ('Fransız Devrim Takvimi\'nde yılın başlangıcı hangi olaya dayandırılmıştır?', 'Cumhuriyetin ilanı (22 Eylül 1792)', ['Bastille\'in alınması (14 Temmuz 1789)', 'Kralın idamı (21 Ocak 1793)', 'Top Oyunu Salonu Yemini (20 Haziran 1789)'], 'Takvim, cumhuriyetin ilanının ertesi gününü I. Yıl\'ın başı saydı; bu tarih aynı zamanda sonbahar ekinoksuna denk geliyordu.'),
  ('1793\'te Paris\'teki Notre-Dame Katedrali\'nde düzenlenen \'Akıl Bayramı\', devrimin hangi yöneliminin örneğidir?', 'Hristiyanlıktan arındırma kampanyasının', ['Papalıkla yapılan uzlaşmanın ve Konkordato\'nun', 'Kraliyetin yeniden kurulmasının', 'Protestanlığın resmî din yapılmasının'], '1793-1794\'te bazı devrimciler kiliseleri kapatıp Akıl Kültü\'nü yaymaya çalıştı; Notre-Dame bir \'Akıl Tapınağı\'na dönüştürüldü.'),
  ('Devrimcilerin metrik sistemi getirmesinin ardındaki düşünce aşağıdakilerden hangisidir?', 'Akla dayalı, evrensel ve bütün yurttaşlar için aynı ölçü düzeni kurmak', ['Kilise takvimini korumak', 'Eski eyaletlerin yerel ölçü ayrıcalıklarını sürdürüp güçlendirmek', 'İngiliz ölçüleriyle uyum sağlamak'], 'Eski Rejim\'de ölçüler bölgeden bölgeye değişiyordu. Metrik sistem, Aydınlanma\'nın akıl ve eşitlik ilkelerini ölçülere taşıdı.'),
  ('Fransa\'daki sömürgelerde köleliği ilk kez Şubat 1794\'te kaldıran meclis hangisidir?', 'Ulusal Konvansiyon', ['Kurucu Meclis', 'Direktuvar', 'Yasama Meclisi'], 'Konvansiyon 16 Pluviôse II. Yıl kararıyla köleliği kaldırdı. Napolyon 1802\'de köleliği yeniden getirdi; kesin kaldırılış 1848\'dedir.'),
  ('Thermidor döneminde Jakoben Kulübü\'nün kapatılması ve fiyat denetimlerinin kaldırılması devrimin hangi yöne kaydığını gösterir?', 'Mülk sahiplerinin çıkarlarını gözeten ılımlı bir çizgiye', ['Daha radikal ve doğrudan katılımcı bir halk demokrasisine', 'Mutlak monarşinin geri gelişine', 'Sosyalist bir ekonomiye'], 'Thermidorcular Terör aygıtını dağıttı ve serbest piyasaya döndü; amaç mülk sahibi burjuvazinin düzenini istikrara kavuşturmaktı.'),
  ('Yıl III Anayasası\'nın yasama organının iki meclisten oluşması hangi kaygının ürünüdür?', 'Tek bir meclisin Terör dönemindeki gibi sınırsız güç kazanmasını önlemek', ['Kralın yetkilerini artırmak', 'Soylulara ve din adamlarına özel ayrı bir meclis ayırmak', 'Papalığa temsil hakkı vermek'], 'Yasama Beşyüzler Meclisi ile Yaşlılar Meclisi arasında bölündü; amaç güçleri dağıtarak hem kraliyetçi hem Jakoben tehlikesine karşı denge kurmaktı.'),
  ('Direktuvar döneminde yasama meclislerinden yasa önerileri yapan genç üyelerden oluşan meclis hangisidir?', 'Beşyüzler Meclisi', ['Yaşlılar Meclisi', 'Tribunat', 'Senato'], 'Beşyüzler Meclisi yasaları önerir, 40 yaşını geçmiş 250 üyeden oluşan Yaşlılar Meclisi ise onları kabul ya da reddederdi.'),
  ('Direktuvar döneminde mülkiyetin kaldırılmasını ve eşitler toplumunu savunan, 1796\'daki \'Eşitler Komplosu\' nedeniyle idam edilen kişi kimdir?', 'Gracchus Babeuf', ['Pierre-Joseph Proudhon', 'Louis Blanc', 'Saint-Simon Kontu'], 'Babeuf\'ün komplosu, sonraki sosyalist ve komünist düşünürler tarafından bir öncü olarak görüldü; 1797\'de idam edildi.'),
  ('Direktuvar rejiminin 1795-1799 arasında defalarca seçim sonuçlarını iptal etmesi ve orduya dayanması, rejimin sonu hakkında neyi açıklar?', 'Ordunun siyasi hakem hâline gelmesinin bir askerî darbeye zemin hazırlamasını', ['Rejimin halkın büyük desteğiyle kalıcılaşıp güçlendiğini', 'Kraliyetin barışçıl biçimde geri döndüğünü', 'Fransa\'nın savaştan tümüyle çekildiğini'], 'Rejim kendi anayasasını sürekli çiğneyince meşruiyetini yitirdi. 1799\'da Sieyès gibi direktörler de bir generalle yeni düzen kurmayı tercih etti.'),
  ('Ekim 1795\'te Paris\'teki kraliyetçi ayaklanmayı Napolyon\'un top ateşiyle dağıttığı olay hangi adla bilinir?', '13 Vendémiaire', ['18 Brumaire VIII. Yıl', '9 Thermidor', '18 Fructidor'], 'Napolyon, Konvansiyon\'u korumak için topları kalabalığa çevirdi (\'bir avuç saçma\'). Bu olay onu Barras\'ın himayesinde İtalya Ordusu komutanlığına taşıdı.'),
  ('Napolyon\'un 1796-1797 İtalya seferinde Avusturyalılara karşı kazandığı zaferlerden biri aşağıdakilerden hangisidir?', 'Arcole', ['Austerlitz', 'Jena', 'Friedland'], 'Lodi, Arcole ve Rivoli, İtalya seferinin ünlü zaferleridir. Austerlitz 1805\'te, Jena 1806\'da, Friedland 1807\'de yapılmıştır.'),
  ('Napolyon\'un İtalya seferi sonunda Avusturya ile 1797\'de imzaladığı antlaşma hangisidir?', 'Campo Formio', ['Lunéville Antlaşması', 'Pressburg', 'Schönbrunn'], 'Campo Formio ile Avusturya Belçika\'yı Fransa\'ya bıraktı ve kuzey İtalya\'daki Cisalpin Cumhuriyeti\'ni tanıdı; karşılığında Venedik\'i aldı.'),
  ('Campo Formio Antlaşması\'yla bin yılı aşkın bağımsızlığı sona eren ve Avusturya\'ya bırakılan İtalyan cumhuriyeti hangisidir?', 'Venedik', ['Cenova', 'Floransa', 'Lucca'], 'Napolyon 1797\'de Venedik Cumhuriyeti\'ne son verdi ve kentin büyük bölümünü Avusturya\'ya bıraktı; bu durum İtalyan yurtseverleri arasında hayal kırıklığı yarattı.'),
  ('Napolyon\'un İtalya\'da Lombardiya merkezli kurduğu ve Fransa\'ya bağlı \'kardeş cumhuriyet\' hangisidir?', 'Cisalpin Cumhuriyeti', ['Batav Cumhuriyeti', 'Helvetya Cumhuriyeti', 'Liguria Cumhuriyeti'], 'Cisalpin Cumhuriyeti Milano merkezliydi. Batav Hollanda\'da, Helvetya İsviçre\'de, Liguria ise Cenova\'da kurulan kardeş cumhuriyetlerdir.'),
  ('Napolyon\'un İtalya\'da yağmalanan sanat eserlerini Paris\'e göndermesi, savaşın hangi yönünü gösterir?', 'Fethedilen ülkelerin kaynaklarının Fransa\'ya aktarılmasını', ['Fransa\'nın sanat eserlerini koruma altına alan bir antlaşma imzalamasını', 'İtalya\'ya Fransız ordusunun yardım ödemesi yapmasını', 'Sanat eserlerinin İtalyan müzelerine dağıtılmasını'], 'İtalya seferi Direktuvar\'a para ve hazine kazandırdı. Louvre\'un koleksiyonları bu dönemde fethedilen ülkelerden getirilen eserlerle büyüdü.'),
  ('Nil Savaşı\'ndaki İngiliz zaferinin Napolyon\'un Mısır seferi üzerindeki etkisi hangisidir?', 'Fransız ordusunun Fransa ile deniz bağlantısının kesilmesi', ['Napolyon\'un Hindistan\'a ulaşması', 'Mısır\'ın kalıcı olarak Fransa\'ya bağlanıp eyalet yapılması', 'Osmanlı\'nın Fransa ile ittifak kurması'], 'Donanmasını yitiren Napolyon ikmal ve takviye alamaz oldu. 1799\'da ordusunu bırakıp gizlice Fransa\'ya döndü.'),
  ('Napolyon\'un 1802\'de kendisini \'ömür boyu konsül\' ilan ettirmesi, rejimin nasıl bir yöne evrildiğini gösterir?', 'Cumhuriyet biçimi altında tek kişi yönetiminin kalıcılaşmasını', ['Yetkilerin meclislere devredilmesini', 'Kraliyetin Bourbonlara geri verilmesini', 'Direktuvar düzenine dönülüp yürütmenin beş kişiye bölünmesini'], 'Ömür boyu konsüllük, iki yıl sonra gelecek imparatorluğun ara basamağıydı; cumhuriyetin kurumları biçimde sürse de güç tek elde toplandı.'),
  ('Napolyon\'un taşrada her departmanın başına doğrudan merkezden atadığı ve yönetimi sıkı biçimde merkeze bağlayan görevli hangisidir?', 'Prefe', ['İntendan', 'Belediye başkanı', 'Bailli'], '1800\'de kurulan prefe düzeni, Fransa\'yı merkeziyetçi biçimde yönetmenin temel aracı oldu ve günümüze kadar sürdü.'),
  ('Lejyon d\'Onör\'ün doğuma değil hizmete göre verilmesi, Napolyon rejiminin hangi devrimci ilkeyi sürdürdüğünü gösterir?', 'Yeteneğe göre yükselme', ['Zümre ayrıcalıklarının ve soyluluk haklarının korunması', 'Kilisenin devlete üstünlüğü', 'Kralın kutsal hakkı'], 'Napolyon \'kariyer yeteneklere açıktır\' ilkesini benimsedi; doğuştan ayrıcalıklar yerine devlete hizmeti ödüllendirdi.'),
  ('Napolyon\'un 1802\'de devlet memuru ve subay yetiştirmek amacıyla kurduğu, askerî disiplinle yönetilen orta öğretim okulları hangisidir?', 'Lise', ['Kolej (collège) adlı okullar', 'Üniversite fakülteleri', 'Köy ilkokulları'], 'Liseler devletin ihtiyaç duyduğu kadroyu yetiştirmek için kuruldu; öğrenciler üniforma giyer, davul sesiyle derse girerdi.'),
  ('Napolyon Kanunu\'nun devrimin hangi kazanımını koruduğu söylenebilir?', 'Feodal ayrıcalıkların kaldırılması ve yasa önünde eşitlik', ['Genel oyla seçilen ve hükümeti denetleyen tek meclis düzeni', 'Kadınlara eşit siyasi haklar verilmesi', 'Basın özgürlüğünün sınırsız hâle getirilmesi'], 'Kanun, doğuştan ayrıcalıkları tanımadı; mülkiyeti ve sözleşme serbestliğini güvenceye aldı. Ancak siyasi özgürlükler Napolyon döneminde kısıtlandı.'),
  ('1801\'de Avusturya ile imzalanan ve Campo Formio düzenlemelerini doğrulayıp Fransa\'ya Ren\'in sol yakasını bırakan antlaşma hangisidir?', 'Lunéville', ['Amiens Antlaşması', 'Tilsit', 'Pressburg'], 'Lunéville Antlaşması ile İkinci Koalisyon\'dan Avusturya çekildi. Ertesi yıl İngiltere ile de barış imzalandı.'),
  ('1802\'de İngiltere ile Fransa arasında imzalanan ve Avrupa\'da yaklaşık bir yıl süren kısa bir barış dönemi açan antlaşma hangisidir?', 'Amiens Antlaşması', ['Paris Antlaşması', 'Utrecht Antlaşması', 'Gent Antlaşması'], 'Amiens Barışı Mart 1802\'de imzalandı; ancak Malta sorunu ve karşılıklı güvensizlik nedeniyle Mayıs 1803\'te savaş yeniden başladı.'),
  ('Amiens Barışı\'nın 1803\'te bozulmasında doğrudan rol oynayan Akdeniz adası hangisidir?', 'Malta', ['Kıbrıs', 'Girit', 'Korsika'], 'Antlaşmaya göre İngilizlerin Malta\'yı boşaltması gerekiyordu; Napolyon\'un Avrupa\'daki yayılmacılığı nedeniyle İngiltere adayı bırakmadı.'),
  ('Napolyon\'un taç giyme töreninde tacı papanın elinden almak yerine kendi başına koyması hangi mesajı vermiştir?', 'Gücünü Kilise\'den değil kendisinden ve ulustan aldığını', ['Papanın Fransa\'daki yetkisini genişlettiğini', 'Bourbon hanedanına bağlılığını', 'İmparatorluğu Avusturya\'ya ve Habsburg hanedanına bağladığını'], 'Papa VII. Pius törende hazırdı ve kutsadı, ancak Napolyon tacı kendisi taktı; böylece otoritesinin dinî onaya bağlı olmadığını gösterdi.'),
  ('Napolyon\'un kardeşi Louis Bonaparte\'ı 1806\'da kral yaptığı ülke hangisidir?', 'Hollanda', ['İspanya', 'Napoli', 'Vestfalya'], 'Louis Hollanda kralı oldu; ancak halkının çıkarlarını gözetip ablukayı tam uygulamayınca 1810\'da tahttan çekildi ve Hollanda Fransa\'ya katıldı.'),
  ('Napolyon\'un kayınbiraderi olan ve 1808\'de Napoli kralı yapılan süvari mareşali kimdir?', 'Joachim Murat', ['Michel Ney', 'Louis-Nicolas Davout', 'Jean Lannes'], 'Murat, Napolyon\'un kız kardeşi Caroline ile evliydi. 1815\'te tahtını geri almaya çalışırken yakalanıp kurşuna dizildi.'),
  ('Napolyon\'un kardeşlerini ve akrabalarını fethettiği ülkelerin tahtlarına oturtması aşağıdakilerden hangisini amaçlıyordu?', 'Avrupa\'da kendine bağlı bir devletler sistemi kurmayı', ['Bu ülkeleri tamamen bağımsız bırakmayı', 'Bourbon hanedanını desteklemeyi', 'Kutsal Roma Germen İmparatorluğu\'nu güçlendirip yeniden canlandırmayı'], 'Bağımlı krallıklar Kıta Ablukası\'nı uygulayacak, asker ve para sağlayacaktı; ancak kardeşler kimi zaman kendi halklarının çıkarını gözetti.'),
  ('Ekim 1805\'te General Mack komutasındaki Avusturya ordusunun kuşatılıp büyük çatışma olmadan teslim olduğu yer hangisidir?', 'Ulm', ['Wagram', 'Aspern', 'Marengo'], 'Napolyon\'un hızlı yürüyüşleri Mack\'in ordusunu Ulm\'da kuşattı; bu manevra, savaşmadan kazanılan zaferlerin klasik örneği sayılır.'),
  ('Ren Konfederasyonu\'nun kurulmasından hemen sonra 1806\'da sona eren köklü siyasi yapı hangisidir?', 'Kutsal Roma Germen İmparatorluğu', ['Lehistan-Litvanya Birliği', 'Venedik Cumhuriyeti', 'Bizans İmparatorluğu'], 'İmparator II. Franz Ağustos 1806\'da Kutsal Roma imparatorluk unvanını bıraktı; böylece yaklaşık bin yıllık yapı resmen dağıldı.'),
  ('Son Kutsal Roma Germen İmparatoru II. Franz\'ın 1804\'te Napolyon\'un imparatorluğuna karşılık olarak aldığı yeni unvan hangisidir?', 'Avusturya İmparatoru', ['Alman Kayzeri ve Prusya Kralı', 'Macaristan Kralı', 'Bohemya Dükü'], 'II. Franz 1804\'te \'Avusturya İmparatoru I. Franz\' unvanını aldı; Kutsal Roma unvanını 1806\'da bıraktığında bu unvanı korudu.'),
  ('Jena ve Auerstedt yenilgilerinin Prusya\'da başlattığı süreç hangisidir?', 'Stein ve Hardenberg\'in yönettiği reform hareketi', ['Prusya\'nın Ren Konfederasyonu\'na katılması', 'Prusya\'nın kalıcı olarak Fransa\'ya ilhakı ve kraliyetin kaldırılması', 'Prusya\'da cumhuriyet ilan edilmesi'], 'Yenilgi, eski düzenin zayıflığını gösterdi. Serfliğin kaldırılması, kent özerkliği ve ordunun yeniden örgütlenmesi gibi reformlar yapıldı.'),
  ('Şubat 1807\'de Doğu Prusya\'da kar fırtınası altında yapılan ve iki taraf için de ağır kayıplarla kesin sonuçsuz kalan savaş hangisidir?', 'Eylau', ['Friedland', 'Wagram', 'Borodino'], 'Eylau Napolyon\'un ilk kez kesin zafer kazanamadığı büyük meydan savaşlarından biridir. Kesin sonuç Haziran 1807\'de Friedland\'de alındı.'),
  ('Tilsit Antlaşması\'nın Prusya için sonuçlarından biri aşağıdakilerden hangisidir?', 'Topraklarının yaklaşık yarısını ve büyük bir savaş tazminatını kaybetmesi', ['Ren\'in sol yakasını Fransa\'dan geri alması', 'Rusya ile birlikte Fransa\'ya karşı ittifak kurup Silezya\'yı kazanması', 'Varşova Dükalığı\'nın kendisine bağlanması'], 'Prusya\'nın Elbe\'nin batısındaki toprakları Vestfalya Krallığı\'na, Polonya toprakları Varşova Dükalığı\'na verildi; ordusu da sınırlandırıldı.'),
  ('Napolyon\'un mareşali olduğu hâlde 1810\'da İsveç veliahtı seçilen ve sonradan Napolyon\'a karşı savaşan kişi kimdir?', 'Jean-Baptiste Bernadotte', ['Louis-Alexandre Berthier, Neuchâtel Prensi', 'Jean-de-Dieu Soult', 'Nicolas Oudinot'], 'Bernadotte İsveç kralı XIV. Karl Johan oldu; bugünkü İsveç kraliyet ailesi onun soyundan gelir. 1813\'te Leipzig\'de müttefiklerle savaştı.'),
  ('Napolyon\'un Avrupa\'yı birleştirmeye dayalı bir \'imparatorluk sistemi\' kurma çabasının, fethedilen halklarda ters etki yaratmasının en önemli nedeni hangisidir?', 'Ağır vergi, asker toplama ve yabancı yönetimin ulusal tepki doğurması', ['Fethedilen halkların Fransız Devrimi\'nden hiç haberi olmaması', 'Napolyon\'un bu ülkelerde hiçbir hukuki ve idari reform yapmamış olması', 'Fransa\'nın bu ülkelere sürekli para yardımı yapması'], 'Reformlar bazı kesimlerce benimsense de, asker ve vergi talepleri ile Fransız üstünlüğü İspanya\'dan Almanya\'ya kadar ulusal direnişi besledi.'),
  ('Beethoven\'ın başlangıçta Napolyon\'a ithaf etmeyi düşündüğü, ancak Napolyon\'un imparatorluğunu ilan etmesi üzerine ithafı sildiği aktarılan senfonisi hangisidir?', '3. Senfoni (Eroica)', ['5. Senfoni', '9. Senfoni', '6. Senfoni (Pastoral)'], 'Beethoven\'ın öğrencisi Ries\'in anlatımına göre besteci, Napolyon\'un imparator olduğunu duyunca \'O da sıradan biri\' diyerek kapak sayfasındaki adı kazıdı.'),
  ('Kıta Ablukası\'nın Fransa\'nın kendi müttefikleri üzerindeki etkisi hangisidir?', 'İngiliz mallarına bağımlı ekonomileri sarsıp kaçakçılığı ve hoşnutsuzluğu artırması', ['Müttefiklerin ekonomilerini kısa sürede zenginleştirmesi', 'İngiltere\'nin hemen barış istemesi', 'Avrupa\'da bütün ticaretin durması ve kaçakçılığın bitmesi'], 'Liman kentleri ticaret kaybetti, sömürge malları pahalandı; kaçakçılık yaygınlaştı ve Fransa\'ya bağlı ülkelerde tepki büyüdü.'),
  ('Napolyon\'un İspanya\'daki savaşı \'İspanyol yarası\' (İspanyol ülseri) diye anması neyi ifade eder?', 'Bitmeyen savaşın asker ve kaynaklarını sürekli tüketmesini', ['İspanya\'nın hızla ve kolayca fethedilmesini', 'İspanya\'dan büyük gelir elde etmesini', 'İspanya\'nın Fransa\'nın en sadık ve en çok kazanç sağlayan müttefiki olmasını'], 'Yüz binlerce Fransız askeri yıllarca İspanya\'da kaldı; bu yük, Napolyon\'un Orta Avrupa ve Rusya\'daki savaşlarını da olumsuz etkiledi.'),
  ('Fransız işgali sırasında Cádiz\'de toplanan İspanyol meclisinin 1812\'de kabul ettiği anayasa hangi yönüyle öne çıkar?', 'Ulusal egemenliğe dayanan liberal bir anayasa olması', ['Mutlak monarşiyi güçlendirmesi', 'İspanya\'yı Fransa\'ya bağlayıp Joseph\'i kral tanıması', 'Engizisyonu yeniden kurması'], '1812 Cádiz Anayasası ulusal egemenliği ve kuvvetler ayrılığını benimsedi; 1820\'de İspanya ve İtalya\'daki ihtilallerin başlıca talebi oldu.'),
  ('Napolyon\'un 1811\'de doğan oğluna verdiği unvan hangisidir?', 'Roma Kralı', ['Napoli Prensi', 'İtalya Kralı', 'Bavyera Dükü'], 'Napoléon François Charles Joseph doğumunda Roma Kralı ilan edildi. Napolyon\'un düşüşünden sonra Avusturya\'da Reichstadt Dükü olarak büyüdü ve 1832\'de genç yaşta öldü.'),
  ('1810-1811 yıllarında Napolyon İmparatorluğu\'nun durumu için aşağıdakilerden hangisi söylenebilir?', 'Kıta Avrupası\'nın büyük bölümü doğrudan ya da dolaylı Fransız denetimindeydi', ['İngiltere Fransız ordusunca işgal edilmişti', 'Rusya Fransa\'ya bağlı bir krallığa dönüşmüştü', 'Napolyon bütün cephelerde yenilgiye uğramıştı'], 'Fransa 130 departmana ulaşmış, bağımlı krallıklar ve müttefiklerle kıtanın çoğunu denetliyordu; İngiltere, Rusya ve Osmanlı bu sistemin dışındaydı.'),
  ('Napolyon\'un 1812\'de Rusya\'ya giren ordusunun dikkat çeken özelliği hangisidir?', 'Askerlerinin önemli bir bölümünün Fransız olmayan müttefik ve bağımlı devletlerden gelmesi', ['Yalnız Fransız gönüllülerden oluşması', 'Çoğunun süvari olması', 'Deniz yoluyla taşınması'], 'Büyük Ordu\'nun 600 bini aşan mevcudunun yarıdan fazlası Almanlar, Polonyalılar, İtalyanlar ve diğer uluslardan oluşuyordu.'),
  ('Napolyon Moskova\'ya girdikten sonra kentte çıkan büyük yangının sefer açısından sonucu ne olmuştur?', 'Ordunun kışı geçirebileceği barınak ve erzakın büyük ölçüde yok olması', ['Çarın hemen barış istemesi', 'Fransızların Moskova\'yı kışlık karargâh ve kalıcı başkent yapması', 'Rus ordusunun kentte teslim olması'], 'Kentin büyük bölümü yandı ve Çar barış önerilerine yanıt vermedi. Napolyon Ekim ortasında geri çekilmeye başladı.'),
  ('Rusya seferinin başarısızlığından sonra Prusya\'nın 1813\'te Fransa\'ya karşı savaşa girmesiyle başlayan ve Almanya\'da ulusal bir coşkuyla anılan sürece ne ad verilir?', 'Kurtuluş Savaşları', ['Otuz Yıl Savaşları', 'Birleşme Savaşları', 'Veraset Savaşları'], '1813-1815 \'Befreiungskriege\', Alman ulusçuluğunun gelişiminde önemli bir dönüm noktası olarak hatırlanır.'),
  ('XVIII. Louis\'nin 1814\'te ilan ettiği ve devrimin bazı kazanımlarını koruyarak sınırlı bir meşruti yönetim öngören belge hangisidir?', 'Anayasa Şartı (Charte)', ['Brumaire Anayasası (VIII. Yıl Anayasası)', 'Ruhban Sivil Anayasası', 'Karlsbad Kararları'], 'Charte constitutionnelle, iki meclisli bir parlamento, yasa önünde eşitlik ve Napolyon Kanunu\'nun sürmesi gibi hükümler içeriyordu; ancak \'kralın lütfu\' olarak sunuldu.'),
  ('Napolyon\'un Elba\'dan kaçıp Mart 1815\'te Fransa kıyısına çıkmasının ardından kendisine karşı gönderilen birliklerin onun saflarına geçmesi neyi gösterir?', 'Ordunun önemli bir bölümünün Bourbonlara bağlanmadığını', ['Halkın Napolyon\'a tümüyle düşman olup Bourbonları desteklediğini', 'Avrupa\'nın Napolyon\'u tanıdığını', 'Bourbonların orduyu güçlendirdiğini'], 'Grenoble yakınında askerler Napolyon\'a ateş etmeyi reddetti; Mareşal Ney de ona katıldı ve Napolyon 20 Mart\'ta savaşmadan Paris\'e girdi.'),
  ('Waterloo Savaşı\'nda Napolyon\'un yenilmesinde belirleyici rol oynayan gelişme hangisidir?', 'Blücher\'in Prusya ordusunun öğleden sonra savaş alanına ulaşması', ['Wellington\'un sabah saatlerinde savaş alanından tamamen çekilmesi', 'Avusturya donanmasının kıyıya çıkarma yapması', 'Napolyon\'un İmparatorluk Muhafızı\'nı İspanya\'da bırakması'], 'Wellington\'un ordusu gün boyu Fransız saldırılarına direndi; Prusyalıların Fransızların sağ kanadına ulaşması dengeyi kesin olarak değiştirdi.'),
  ('Viyana Kongresi\'nde İngiltere\'yi temsil eden dışişleri bakanı kimdir?', 'Lord Castlereagh', ['William Pitt', 'George Canning', 'Lord Palmerston'], 'Castlereagh kıtada güç dengesini korumaya çalıştı; İngiltere için asıl kazanımlar deniz üsleri ve sömürgelerdi.'),
  ('Viyana Kongresi\'nde sınırlar çizilirken ulusal duyguların çoğunlukla göz ardı edilmesi, sonraki yarım yüzyılı nasıl etkilemiştir?', 'Ulusçu ayaklanmaların ve birlik hareketlerinin Viyana düzenini sürekli zorlaması', ['Avrupa\'da ulusçuluğun tamamen ortadan kalkması', 'Bütün ulusların bağımsız devletlere kavuşması', 'Büyük güçlerin bütün sömürgelerinden çekilmesi'], 'Belçikalılar Hollanda\'ya, İtalyanların bir bölümü Avusturya\'ya, Polonyalılar Rusya\'ya bağlandı. 1830 ve 1848 ayaklanmaları bu düzene karşı patlak verdi.'),
  ('Viyana Kongresi\'nde Fransa\'nın kuzeyinde bir tampon oluşturmak için eski Avusturya Hollandası (Belçika) hangi devlete bağlanmıştır?', 'Hollanda Krallığı', ['Prusya Krallığı', 'İngiltere Krallığı', 'Avusturya İmparatorluğu'], 'Belçika ile Hollanda, Orange hanedanının yönetiminde Birleşik Hollanda Krallığı olarak birleştirildi; bu birlik 1830\'da Belçika ihtilaliyle dağıldı.'),
  ('Alman Konfederasyonu\'nun ortak meclisi (Bundestag) hangi kentte toplanırdı?', 'Frankfurt', ['Berlin', 'Viyana', 'Münih'], 'Federal Meclis Frankfurt am Main\'da toplanıyordu. Kurum, üye devletlerin elçilerinden oluşan bir kurul niteliğindeydi.'),
  ('Viyana Kongresi\'nde Avusturya\'nın İtalya\'daki kazancı hangisidir?', 'Lombardiya-Venedik Krallığı', ['Piyemonte ve Sardinya adası ile Nice', 'Napoli ve Sicilya', 'Papalık Devleti'], 'Avusturya, Lombardiya ve Venedik\'i doğrudan aldı; Toskana ve Modena gibi düklüklerde de Habsburg aile üyeleri hüküm sürdü.'),
  ('Viyana Kongresi\'nde Polonya topraklarının büyük bölümünden oluşturulup Rus çarının kral olduğu yapı hangisidir?', 'Kongre Polonyası', ['Varşova Dükalığı', 'Galiçya ve Lodomerya Krallığı', 'Litvanya Büyük Dükalığı'], 'Çar I. Aleksandr kendi anayasası olan bir Polonya Krallığı\'nın kralı oldu; bu özerklik 1830 ayaklanmasından sonra büyük ölçüde kaldırıldı.'),
  ('Viyana Kongresi düzenlemeleriyle İsviçre\'nin uluslararası statüsü için hangisi doğrudur?', 'Kalıcı tarafsızlığı büyük güçlerce tanındı', ['Avusturya\'ya bağlanıp bir Habsburg dükalığına dönüştü', 'Fransa\'ya ilhak edildi', 'Bağımsızlığı kaldırıldı'], '1815\'te İsviçre\'nin daimi tarafsızlığı ve toprak bütünlüğü güvence altına alındı; bu statü günümüze kadar sürmüştür.'),
  ('Viyana Kongresi\'nde İngiltere\'nin elde ettiği kazanımlar hangisinde doğru verilmiştir?', 'Ümit Burnu, Seylan ve Malta gibi stratejik deniz üsleri', ['Belçika ve Ren bölgesi', 'Lombardiya ve Venedik', 'Finlandiya ve Polonya\'nın doğu toprakları ile Kırım'], 'İngiltere Avrupa\'da toprak istemedi; deniz yollarını denetleyecek üs ve kolonileri tercih etti.'),
  ('Viyana Kongresi\'nin sona ermesinden kısa süre önce kongrenin çalışmasını kesintiye uğratan olay hangisidir?', 'Napolyon\'un Elba\'dan dönüşü', ['Belçika ihtilali', 'Yunan ayaklanması', 'Dekabrist isyanı ve çarın ölümü'], 'Napolyon Mart 1815\'te Fransa\'ya döndü. Kongre müzakereleri sürdü; Son Senet 9 Haziran 1815\'te, Waterloo\'dan dokuz gün önce imzalandı.'),
  ('Kutsal İttifak\'tan farklı olarak İngiltere\'nin de katıldığı ve Fransa\'yı denetim altında tutmayı amaçlayan 1815 ittifakı hangisidir?', 'Dörtlü İttifak', ['Üçlü İtilaf', 'Üç İmparator Ligi', 'Kutsal Lig'], 'İngiltere, Rusya, Avusturya ve Prusya, 1815 düzenini korumak ve düzenli kongreler yapmak için Dörtlü İttifak\'ı kurdu.'),
  ('1815 sonrasında büyük güçlerin sorunları düzenli kongrelerde görüşerek savaşı önlemeye çalıştığı işbirliği düzenine ne ad verilir?', 'Avrupa Uyumu (Avrupa Konseri)', ['Kıta Ablukası (Berlin Kararnamesi)', 'Kurtuluş Savaşları', 'Silahlı Tarafsızlık Ligi'], 'Concert of Europe, uzun bir genel savaşın tekrarını önlemek amacıyla büyük güçlerin danışmasına dayanıyordu; Kırım Savaşı bu düzeni sarstı.'),
  ('1819\'da Metternich\'in önderliğinde Alman Konfederasyonu\'nda kabul edilen ve basına sansür, üniversitelere denetim getiren kararlar hangisidir?', 'Karlsbad Kararları', ['Troppau Protokolü', 'Berlin Kararnamesi', 'Olmütz Uzlaşması'], 'Oyun yazarı Kotzebue\'nin bir öğrenci tarafından öldürülmesi bahane edilerek öğrenci birlikleri yasaklandı ve liberal-ulusçu faaliyetler bastırıldı.'),
  ('Metternich\'in çok uluslu Habsburg devleti için ulusçuluğu özellikle tehlikeli görmesinin nedeni nedir?', 'Ulusçuluğun imparatorluğu oluşturan halkları ayrılığa yöneltebilecek olması', ['Avusturya\'nın tek bir ulustan oluşması', 'Ulusçuluğun yalnız Fransa\'yı ilgilendirmesi', 'Habsburgların hiçbir Alman olmayan topraklara ve halklara sahip olmaması'], 'Habsburg ülkesinde Almanlar, Macarlar, Çekler, Polonyalılar, İtalyanlar, Hırvatlar ve diğerleri yaşıyordu; her ulusçu talep devletin bütünlüğünü sorgulatıyordu.'),
  ('1821\'de Napoli\'deki anayasal rejimi askerî müdahaleyle yıkıp mutlak monarşiyi geri getiren devlet hangisidir?', 'Avusturya', ['Fransa', 'Rusya', 'İspanya'], 'Laibach Kongresi\'nin yetkisiyle Avusturya ordusu Napoli\'ye girdi ve Bourbon kralının mutlak yetkilerini geri verdi; aynı yıl Piyemonte\'deki ayaklanmayı da bastırdı.'),
  ('Dekabrist ayaklanmasının liderlerinin çoğunun Napolyon savaşlarına katılmış subaylar olması neyi açıklar?', 'Avrupa\'da gördükleri liberal fikirlerin Rusya\'ya taşınmasını', ['Rusya\'nın Fransa\'ya bağlanmak istemesini', 'Ayaklanmanın köylülerce yönetildiğini', 'Ordunun bütünüyle çarı ve otokrasiyi desteklediğini göstermesini'], 'Paris\'e kadar giden Rus subaylar anayasal yönetimi ve hukuk düzenini gördü; geri döndüklerinde Rusya\'daki serflik ve otokrasiyi sorguladılar.'),
  ('1821\'de Prut Irmağı\'nı geçip Boğdan\'da Yunan ayaklanmasını başlatan, Rus ordusunda general olarak görev yapmış Rum lider kimdir?', 'Aleksandros İpsilantis', ['İoannis Kapodistrias', 'Theodoros Kolokotronis', 'Markos Botsaris'], 'İpsilantis\'in Tuna beyliklerindeki ayaklanması 1821\'de Drăgășani\'de bastırıldı; ancak aynı yıl Mora\'da başlayan ayaklanma bağımsızlık savaşına dönüştü.'),
  ('İngiliz romantik şair Lord Byron\'ın 1824\'te Yunan ayaklanmasına katılmak için gittiği ve hastalanarak öldüğü kasaba hangisidir?', 'Mesolongi', ['Atina', 'Navarin', 'Nafplio'], 'Byron\'ın ölümü Batı Avrupa\'da Yunan davasına olan sempatiyi (Filhelenizm) güçlendirdi.'),
  ('Batı Avrupa\'da Yunan ayaklanmasına destek veren aydın ve sanatçılardan oluşan akım hangi adla anılır?', 'Filhelenizm', ['Panslavizm', 'Pancermenizm', 'Ultramontanizm'], 'Filhelenler, Antik Yunan mirasına duydukları hayranlıkla Yunan davasını desteklediler; Delacroix\'nın \'Sakız Katliamı\' tablosu bu havayı yansıtır.'),
  ('1827 Navarin deniz savaşında Osmanlı-Mısır donanmasını yakan birleşik filo hangi devletlerden oluşuyordu?', 'İngiltere, Fransa ve Rusya', ['Avusturya, Prusya ve Rusya', 'İngiltere, İspanya ve Hollanda', 'Fransa, Avusturya ve Sardinya'], 'Londra Antlaşması (1827) uyarınca Yunanistan\'a özerklik dayatmak isteyen üç büyük güç, Navarin\'de Osmanlı-Mısır filosunu yok etti.'),
  ('Bağımsız Yunanistan\'ın ilk kralı olarak 1832\'de büyük güçler tarafından seçilen prens hangi ülkedendi?', 'Bavyera', ['Danimarka', 'İngiltere', 'Rusya'], 'Bavyera kralının oğlu Otto, 17 yaşında Yunanistan kralı oldu; 1862\'de devrildi ve yerine Danimarkalı I. Yorgo geçti.'),
  ('Yunanistan\'ın tam bağımsızlığını tanıyan 1830 belgesi hangisidir?', 'Londra Protokolü', ['Edirne Antlaşması', 'Ayastefanos Antlaşması', 'Paris Antlaşması'], 'İngiltere, Fransa ve Rusya\'nın imzaladığı 1830 Londra Protokolü, Yunanistan\'ı büyük güçlerin koruması altında bağımsız bir devlet olarak tanıdı.'),
  ('1815-1830 döneminde Avrupa\'da gizli örgütlerin (örneğin İtalya\'daki Karbonari) yaygınlaşmasının nedeni nedir?', 'Liberal ve ulusçu düşüncelerin açıkça savunulmasının sansür ve polis baskısıyla engellenmesi', ['Hükümetlerin bu örgütleri resmî olarak teşvik etmesi', 'Halkın siyasete ilgisini tamamen yitirmesi', 'Basın özgürlüğünün çok geniş olması'], 'Açık siyasi faaliyet yasaklanınca muhalefet gizli örgütlere yöneldi; Karbonari 1820-1821 Napoli ve Piyemonte ayaklanmalarında rol oynadı.'),
  ('X. Charles\'ın Temmuz 1830\'da yayımladığı ve 1830 devrimini doğrudan tetikleyen kararnameler neyi öngörüyordu?', 'Basın özgürlüğünü kaldırıp meclisi dağıtmak ve seçim yasasını değiştirmek', ['Köleliği kaldırmak', 'Cumhuriyeti ilan edip bütün erkeklere oy hakkı tanımak', 'Kilise topraklarını satmak'], 'Temmuz Kararnameleri (Saint-Cloud Kararnameleri) gazeteleri susturmayı ve seçmen sayısını daha da azaltmayı amaçlıyordu; Paris halkı barikat kurdu.'),
  ('Louis-Philippe\'in \'Fransa Kralı\' yerine \'Fransızların Kralı\' unvanını alması neyi simgeler?', 'Tahtını ilahi haktan çok ulusun onayına dayandırdığını', ['Mutlak monarşiye döndüğünü', 'Bourbon geleneğini aynen sürdürüp Reims\'te taç giymeyi seçtiğini', 'İmparatorluk ilan ettiğini'], 'Bu unvan, 1791\'deki anayasal monarşi anlayışını hatırlatıyordu; kral egemenliği ulusla paylaşan bir figür olarak sunuldu.'),
  ('1839 Londra Antlaşması\'nın Belçika için en önemli hükmü hangisidir?', 'Bağımsızlığının ve sürekli tarafsızlığının büyük güçlerce güvenceye alınması', ['Belçika\'nın Fransa\'ya ilhak edilmesi', 'Belçika\'nın Hollanda\'ya geri verilmesi', 'Belçika\'nın Alman Konfederasyonu\'na katılması'], '1839 antlaşmasında Prusya da güvenceye imza attı. Almanya\'nın 1914\'te bu tarafsızlığı çiğnemesi İngiltere\'nin savaşa girme gerekçelerinden biri oldu.'),
  ('1830-1831\'de Rus yönetimine karşı başlayan ve bastırılmasının ardından Kongre Polonyası\'nın anayasasının kaldırıldığı ayaklanma hangisidir?', 'Kasım Ayaklanması', ['Ocak Ayaklanması', 'Kościuszko Ayaklanması', 'Varşova Ayaklanması'], 'Kasım 1830\'da Varşova\'da başlayan ayaklanma 1831\'de bastırıldı. Ocak Ayaklanması ise 1863\'te gerçekleşmiştir.'),
  ('Şubat 1848 Devrimi\'nden sonra Fransa\'da kurulan geçici hükümette yer alan şair ve devlet adamı kimdir?', 'Alphonse de Lamartine', ['François Guizot', 'Victor Hugo', 'Honoré de Balzac'], 'Lamartine kırmızı bayrak yerine üç renkli bayrağın korunmasını sağladı ve geçici hükümetin dışişlerini yönetti.'),
  ('\'Emeğin Örgütlenmesi\' adlı eseriyle devlet desteğiyle kurulacak işçi atölyelerini savunan ve 1848 geçici hükümetinde yer alan sosyalist kimdir?', 'Louis Blanc', ['Auguste Blanqui', 'Charles Fourier', 'Pierre Leroux'], 'Louis Blanc \'çalışma hakkı\'nı savundu. Ulusal Atölyeler onun düşüncesinin çarpıtılmış bir uygulaması olarak görülür.'),
  ('Haziran 1848\'de Paris işçi ayaklanmasını ordu ile kanlı biçimde bastıran general kimdir?', 'Louis-Eugène Cavaignac', ['Patrice de Mac-Mahon', 'Georges Boulanger', 'Nicolas Changarnier'], 'Cavaignac\'ın bastırmasında binlerce kişi öldü ya da sürüldü. Haziran Günleri, cumhuriyetçi burjuvazi ile işçiler arasındaki kopuşu simgeler.'),
  ('Haziran 1848 olaylarının Fransız siyasetindeki önemi en iyi hangi ifadeyle açıklanır?', 'Burjuva cumhuriyetçiler ile işçiler arasındaki ittifakın kopması', ['Monarşinin hemen geri gelmesi', 'Sosyalistlerin iktidarı ele geçirmesi', 'Fransa\'nın Avusturya\'ya savaş açması'], 'Şubat\'ta birlikte savaşan kesimler Haziran\'da karşı karşıya geldi; mülk sahipleri düzen için güçlü bir yönetim aramaya başladı.'),
  ('Louis-Napoléon\'un 1848 seçimlerinde köylülerden büyük destek almasının temel nedeni nedir?', 'Bonaparte adının şan ve düzen çağrışımı', ['Kapsamlı bir toprak reformu ve kooperatif programı açıklaması', 'Paris işçilerinin lideri olması', 'Kraliyet ailesinden gelmesi'], 'Köylüler için Napolyon adı devrimin kazanımlarını koruyan güçlü bir yönetimi simgeliyordu; Louis-Napoléon herkese bir şey vaat eden belirsiz bir program sundu.'),
  ('Louis-Napoléon\'un 2 Aralık 1851 darbesini yapmasının anayasal gerekçesi neydi?', 'Cumhurbaşkanının yeniden seçilmesini yasaklayan hükmün kaldırılmaması', ['Meclisin onu ömür boyu imparator seçip krallığı kaldırması', 'Avusturya\'nın Fransa\'ya saldırması', 'Kralın ölmesi'], '1848 Anayasası cumhurbaşkanına ikinci bir dört yıllık dönem tanımıyordu; meclis değişikliği reddedince Louis-Napoléon darbeyle meclisi dağıttı.'),
  ('Haussmann\'ın Paris\'te geniş ve düz bulvarlar açmasının, sağlık ve güzelliğin yanında hangi siyasi amaca da hizmet ettiği ileri sürülür?', 'Barikat kurmayı zorlaştırıp ordunun hızlı hareketini kolaylaştırmak', ['Kraliyet saraylarını yeniden inşa etmek', 'Kentin nüfusunu azaltmak için tarım alanı açmak', 'Kiliselere daha geniş alan bırakmak'], '1830 ve 1848\'de dar sokaklar barikatlar için elverişliydi. Geniş bulvarlar asker ve topun hareketini kolaylaştırıyordu.'),
  ('III. Napolyon\'un eşi olan ve İspanyol soylu ailesinden gelen imparatoriçe kimdir?', 'Eugénie de Montijo', ['Joséphine de Beauharnais', 'Marie-Louise', 'Hortense de Beauharnais'], 'Eugénie 1853\'te III. Napolyon ile evlendi; imparatorluğun sonuna kadar sarayda ve dış politikada etkili oldu.'),
  ('1858\'de III. Napolyon\'a bomba ile suikast girişiminde bulunan İtalyan ulusçu kimdir?', 'Felice Orsini', ['Giuseppe Mazzini', 'Gaetano Bresci', 'Carlo Pisacane'], 'Orsini\'nin girişimi başarısız oldu ve idam edildi; ancak mektubundaki İtalya\'ya yardım çağrısı III. Napolyon\'u etkiledi ve Plombières görüşmesinin zeminini hazırladı.'),
  ('III. Napolyon\'un 1860\'larda meclisin yetkilerini artırıp basın denetimini gevşettiği döneme ne ad verilir?', 'Liberal İmparatorluk', ['Otoriter Restorasyon', 'Ahlaki Düzen dönemi', 'Yüz Gün dönemi'], '1860\'tan itibaren yapılan reformlar 1870\'te parlamenter bir anayasa ile doruğa ulaştı; aynı yıl yapılan plebisit imparatorluğu destekledi.'),
  ('III. Napolyon\'un Paris\'te 1855 ve 1867\'de düzenlettiği büyük fuarlar hangi adla bilinir?', 'Dünya Sergileri', ['Olimpiyat Oyunları', 'Kristal Saray Fuarları', 'Salon des Refusés'], 'Londra\'daki 1851 Büyük Sergisi\'ni örnek alan bu sergiler Fransa\'nın sanayi ve kültür gücünü sergilemeyi amaçlıyordu.'),
  ('Fransız Devrimi ile başlayan dönemde Fransa\'da rejim değişikliklerini kronolojik sıraya koyan seçenek hangisidir?', 'Birinci Cumhuriyet, Birinci İmparatorluk, Restorasyon, Temmuz Monarşisi', ['Restorasyon, Birinci Cumhuriyet, Temmuz Monarşisi, Birinci İmparatorluk', 'Birinci İmparatorluk, Birinci Cumhuriyet, Restorasyon, Temmuz Monarşisi', 'Temmuz Monarşisi, Restorasyon, Birinci İmparatorluk, Birinci Cumhuriyet'], 'Sıra: Birinci Cumhuriyet (1792), Birinci İmparatorluk (1804), Restorasyon (1814/1815), Temmuz Monarşisi (1830).'),
  ('Frankfurt Parlamentosu\'nda Alman birliğinin sınırları tartışılırken Avusturya\'yı da kapsayan çözümü savunanlara ne ad verilir?', 'Büyük Almanyacılar', ['Küçük Almanyacılar ve Prusya merkezli birlikçiler', 'Pancermenistler', 'Ren Konfederasyoncular'], 'Großdeutsch çözüm Avusturya\'nın Alman topraklarını da kapsıyordu; Kleindeutsch çözüm ise Avusturya\'yı dışarıda bırakıp Prusya önderliğini öngörüyordu.'),
  ('Frankfurt Parlamentosu\'nun Alman birliğini sağlayamamasının en önemli nedeni hangisidir?', 'Kendi ordusu ve yürütme gücü olmaması', ['Üyelerinin tamamının Fransız olması ve Almanca bilmemesi', 'Bütün Alman prenslerinin birliğe gönülden destek vermesi', 'Avusturya\'nın parlamentoyu finanse etmesi'], 'Parlamento kararlarını uygulatacak bir güce sahip değildi; Prusya ve Avusturya orduları kendi hükümdarlarına bağlı kaldı ve parlamento 1849\'da dağıtıldı.'),
  ('Avusturya\'nın 1849\'da Macar devrimini bastırabilmesi için yardım istediği devlet hangisidir?', 'Rusya', ['Prusya krallığı ve Saksonya ordusu', 'Fransa', 'İngiltere'], 'Çar I. Nikola, \'Kutsal İttifak\' ruhuyla yaklaşık 200 bin asker gönderdi; Macar ordusu Ağustos 1849\'da Világos\'ta teslim oldu.'),
  ('1848 devrimlerinin genel olarak başarısız olmasının nedenlerinden biri aşağıdakilerden hangisidir?', 'Liberaller, radikaller ve farklı uluslar arasındaki derin ayrılıklar', ['Devrimcilerin her yerde tek bir program etrafında birleşmesi', 'Orduların tamamen devrimcilere katılması', 'Hükümdarların devrimlerden hiç etkilenmemesi'], 'Ilımlı liberaller toplumsal devrimden korktu, uluslar birbirinin taleplerine karşı çıktı; ordular hükümdarlara sadık kalınca karşı devrim kolayca kazandı.'),
  ('1850\'de Prusya\'nın Avusturya ve Rusya\'nın baskısıyla kendi önderliğindeki Alman birliği planından vazgeçtiği anlaşma hangisidir?', 'Olmütz Uzlaşması', ['Prag Barışı', 'Gastein Sözleşmesi', 'Frankfurt Antlaşması'], 'Prusyalılar bu anlaşmayı \'Olmütz aşağılanması\' diye andılar; Alman Konfederasyonu Avusturya\'nın başkanlığında yeniden canlandırıldı.'),
  ('Halkların Baharı\'nın İngiltere ve Rusya\'da büyük bir devrime dönüşmemesinin ortak açıklaması için hangisi en uygundur?', 'İngiltere\'de reformların gerginliği azaltması, Rusya\'da ise sıkı baskı düzeni', ['İki ülkede de cumhuriyet ilan edilmiş olması', 'İki ülkenin de Fransa\'ya bağlı olması', 'İki ülkede de sanayi bulunmaması'], 'İngiltere 1832 ve 1846 reformlarıyla burjuvaziyi sisteme katmıştı; Rusya\'da ise I. Nikola\'nın polis devleti muhalefete hareket alanı bırakmıyordu.'),
  ('Mazzini\'nin İtalyan birliği konusundaki görüşü Cavour\'unkinden hangi yönüyle ayrılır?', 'Halk ayaklanmasıyla kurulacak bir cumhuriyeti savunması', ['Birliğin diplomasi ve Fransa ittifakıyla Piyemonte monarşisi altında kurulmasını istemesi', 'İtalya\'nın bölünmüş kalmasını istemesi', 'Papanın başkanlığında bir federasyon önermesi'], 'Cavour, diplomasi ve büyük güç desteğiyle Savoy hanedanı önderliğinde bir krallık kurmayı amaçladı; Mazzini ise devrimci ve cumhuriyetçiydi.'),
  ('1848\'de Avusturya\'ya savaş açıp Custoza\'da ve 1849\'da Novara\'da yenilen, ardından tahttan çekilen Piyemonte kralı kimdir?', 'Carlo Alberto', ['II. Vittorio Emanuele', 'I. Umberto', 'I. Vittorio Emanuele'], 'Novara yenilgisinden sonra Carlo Alberto oğlu II. Vittorio Emanuele lehine tahttan feragat etti ve Portekiz\'de sürgünde öldü.'),
  ('Carlo Alberto\'nun 1848\'de verdiği ve 1861\'den sonra bütün İtalya Krallığı\'nın anayasası olarak yürürlükte kalan anayasa hangisidir?', 'Statuto Albertino', ['Cádiz Anayasası', 'Charte', 'Roma Cumhuriyeti Anayasası'], '1848 devrimlerinden sonra İtalya\'da yürürlükte kalan tek anayasa Piyemonte\'ninkiydi; bu durum Piyemonte\'yi İtalyan liberallerinin gözünde öncü yaptı.'),
  ('1849\'da kurulan ve Mazzini\'nin de yönetiminde yer aldığı Roma Cumhuriyeti\'ni yıkarak papanın yönetimini geri getiren yabancı güç hangisidir?', 'Fransa', ['Avusturya ve Napoli\'nin ortak kuvvetleri', 'İspanya', 'Prusya'], 'Louis-Napoléon\'un gönderdiği Fransız ordusu, Garibaldi\'nin savunmasına rağmen Temmuz 1849\'da Roma\'ya girdi; Fransız askerleri kısa bir ara dışında 1870\'e kadar kentte kaldı.'),
  ('Cavour\'un Piyemonte\'yi 1855\'te Kırım Savaşı\'na sokmasının asıl amacı neydi?', 'İtalyan sorununu büyük güçlerin gündemine taşımak', ['Rusya\'dan toprak kazanıp Karadeniz\'e kıyısı olan bir liman edinmek', 'Osmanlı\'dan Mısır\'ı almak', 'Avusturya ile ittifak kurmak'], 'Piyemonte\'nin savaşa katılması ona Paris Barış Konferansı\'nda bir yer kazandırdı; Cavour orada İtalya\'daki Avusturya egemenliğini gündeme getirdi.'),
  ('Cavour ile III. Napolyon\'un 1858\'de gizlice görüşüp Avusturya\'ya karşı ortak savaş planladıkları kaplıca kasabası hangisidir?', 'Plombières', ['Villafranca', 'Biarritz', 'Vichy'], 'Plombières\'de Fransa\'nın Piyemonte\'ye yardım etmesi karşılığında Nice ve Savoie\'yi alması kararlaştırıldı.'),
  ('Garibaldi\'nin 1860\'ta Bin Kişilik gönüllü birliğiyle Sicilya\'da karaya çıktığı yer hangisidir?', 'Marsala', ['Palermo', 'Napoli', 'Messina'], 'Garibaldi Mayıs 1860\'ta Marsala\'ya çıktı, Calatafimi\'de Bourbon birliklerini yendi ve kısa sürede Sicilya\'yı ele geçirdi.'),
  ('Garibaldi\'nin 1860\'ta güneyde ele geçirdiği toprakları cumhuriyet ilan etmek yerine II. Vittorio Emanuele\'ye teslim ettiği tarihî buluşma nerede gerçekleşmiştir?', 'Teano', ['Torino', 'Marsala', 'Plombières'], 'Ekim 1860\'taki Teano buluşmasında Garibaldi krala \'İtalya Kralı\' diye seslendi ve fethettiği toprakları ona bıraktı.'),
  ('Garibaldi\'nin güney İtalya\'yı krala teslim etmesi, birlik sürecinin hangi özelliğini ortaya koyar?', 'Devrimci girişimin monarşist bir çerçeveye bağlanmasını', ['Cumhuriyetçilerin bütün İtalya\'da iktidara geldiğini', 'Papanın birliğe önderlik ettiğini', 'Avusturya\'nın güneyi yönettiğini'], 'Garibaldi cumhuriyetçi olmasına karşın iç savaştan kaçınmak için Savoy hanedanını kabul etti; böylece birlik monarşi altında tamamlandı.'),
  ('İtalya, Venedik bölgesini 1866\'da nasıl kazanmıştır?', 'Prusya ile ittifak yapıp Avusturya\'ya karşı savaşarak', ['Fransa\'dan satın alarak', 'Papalıkla yapılan bir antlaşmayla', 'Avusturya\'yı tek başına Custoza ve Lissa\'da kesin bir zaferle yenerek'], 'İtalya, Custoza ve Lissa\'da yenilmesine rağmen Prusya\'nın Avusturya\'yı yenmesi sayesinde Venedik\'i (Fransa aracılığıyla) aldı.'),
  ('İtalyan birlikleri Roma\'ya hangi gelişmenin ardından 1870\'te girebilmiştir?', 'Fransız garnizonunun Prusya savaşı nedeniyle çekilmesi', ['Papanın Roma\'yı gönüllü olarak bir antlaşmayla İtalya\'ya bırakması', 'Avusturya\'nın Roma\'yı İtalya\'ya devretmesi', 'Garibaldi\'nin Roma\'da cumhuriyet ilan etmesi'], 'Fransız-Prusya Savaşı başlayınca Fransız askerleri Roma\'dan ayrıldı; İtalyan ordusu 20 Eylül 1870\'te Porta Pia\'dan kente girdi.'),
  ('Piyemonteli devlet adamı Massimo d\'Azeglio\'ya atfedilen \'İtalya\'yı yaptık, şimdi İtalyanları yapmalıyız\' sözü hangi sorunu dile getirir?', 'Siyasi birliğin ulusal kimlik birliğini kendiliğinden getirmemesini', ['İtalya\'nın henüz hiç toprağı olmamasını', 'İtalyanların başka bir ülkeye göç etmesini', 'İtalya\'nın krallık yerine cumhuriyet olmasını'], '1861\'de nüfusun çok küçük bir bölümü standart İtalyanca konuşuyordu; bölgesel farklılıklar, okuma yazma ve ekonomik uçurumlar büyüktü.'),
  ('Birlikten sonra İtalya\'nın güney bölgelerine verilen ve kuzeyle arasındaki ekonomik farkı anlatan kavram hangisidir?', 'Mezzogiorno sorunu', ['Irredentizm sorunu ve Trento meselesi', 'Risorgimento', 'Roma sorunu'], 'Kuzey sanayileşirken güney yoksul ve tarıma dayalı kaldı; 1860\'larda güneyde \'eşkıyalık\' denilen geniş çaplı bir direniş bastırıldı.'),
  ('Verdi\'nin \'Nabucco\' operasındaki \'Va, pensiero\' korosunun İtalyan ulusçuları arasında sevilmesinin nedeni nedir?', 'Sürgündeki bir halkın yurt özlemini anlatması', ['Bir Avusturya imparatoruna övgü olması', 'Papalığın resmî ilahisi olması', 'Fransız Devrimi\'ni konu alması'], 'Babil\'deki sürgün Yahudilerin yurt özlemini dile getiren koro, yabancı yönetim altındaki İtalyanlarca kendi durumlarının ifadesi olarak benimsendi.'),
  ('Cavour\'un İtalyan birliği sürecindeki rolünü en iyi değerlendiren ifade hangisidir?', 'Büyük güçlerin rekabetini kullanarak Piyemonte\'nin genişlemesini sağlaması', ['Halkı silahlandırıp Avusturya\'yı tek başına yenmesi', 'Papalık Devleti\'ni ilk yıllarda doğrudan yönetmesi', 'Birlik kurulmadan önce Fransa\'ya sürgün edilmesi'], 'Cavour, III. Napolyon\'u Avusturya\'ya karşı savaşa çekti ve Garibaldi\'nin güneydeki başarısını da monarşi lehine yönlendirdi; 1861\'de krallık ilanından kısa süre sonra öldü.'),
  ('Zollverein\'in Alman birliği açısından önemi en iyi hangi ifadeyle açıklanır?', 'Ekonomik bütünleşmenin Prusya önderliğinde siyasi birliğe zemin hazırlaması', ['Avusturya\'yı Alman ekonomisinin merkezi yapması', 'Alman devletleri arasında yeni gümrük duvarları kurması', 'Almanya\'yı Fransa\'ya ekonomik olarak bağlaması'], 'Ortak pazar, demiryolları ve ticaret, Alman orta sınıfını Prusya\'ya yakınlaştırdı; Avusturya\'nın dışarıda kalması onun etkisini azalttı.'),
  ('Zollverein\'in fikir babası sayılan ve ulusal ekonomiyi korumak için gümrük birliği ve demiryolu ağını savunan Alman iktisatçı kimdir?', 'Friedrich List', ['Adam Smith', 'Max Weber', 'Karl Marx'], 'List, \'Ulusal Ekonomi Politiği Sistemi\' adlı eserinde gelişmekte olan sanayileri koruyucu gümrüklerle desteklemeyi savundu.'),
  ('Bismarck 1862\'de hangi bunalımı çözmek için Prusya başbakanlığına getirilmiştir?', 'Ordu reformu bütçesi yüzünden kral ile meclis arasında çıkan anayasa bunalımı', ['Fransa ile Ren sınırında çıkan bir savaşın kaybedilmesi', 'Avusturya\'nın Prusya\'yı işgali', 'Kralın ölümü'], 'Liberal çoğunluklu meclis ordu reformu için bütçe onaylamıyordu; Bismarck bütçesiz yönetmeyi göze alarak reformları uyguladı.'),
  ('Bismarck\'ın Alman birliğini kurma yöntemi ile 1848 Frankfurt Parlamentosu\'nun yöntemi arasındaki temel fark hangisidir?', 'Bismarck\'ın birliği Prusya ordusu ve savaşlarla yukarıdan kurması', ['Bismarck\'ın halkoylaması ve parlamento kararıyla ilerlemesi', 'Frankfurt Parlamentosu\'nun Avusturya\'yı savaşla yenmesi', 'İkisinin de cumhuriyet kurmayı amaçlaması'], 'Frankfurt liberalleri anayasa ve meclis yoluyla birlik istedi; Bismarck ise \'demir ve kan\' politikasıyla üç savaş sonunda birliği kurdu.'),
  ('Prusya piyadesinin 1866\'da Avusturyalılara üstünlük sağlamasında etkili olan silah hangisidir?', 'Dreyse iğneli tüfeği', ['Makineli tüfek ve ağır sahra topu birlikte', 'Ağızdan dolma tüfek', 'Uzun mızrak'], 'Kuyruktan dolma iğneli tüfek, askerin yatarak ve hızlı ateş etmesine olanak tanıyordu; Avusturyalılar hâlâ ağızdan dolma tüfek kullanıyordu.'),
  ('1866 Prag Barışı\'nda Bismarck\'ın Avusturya\'dan toprak almaması ve onu küçük düşürmemesinin nedeni neydi?', 'Avusturya\'yı gelecekte düşman değil olası bir müttefik olarak tutmak', ['Kral I. Wilhelm\'in Viyana\'ya girip Habsburgları devirmek istememesi', 'Fransa\'nın Avusturya\'yı işgal etmesi', 'Prusya ordusunun aslında yenilmiş olması'], 'Bismarck, Kral ve generallerin Viyana\'ya yürüme isteğine karşı çıktı; amacı yalnızca Avusturya\'yı Alman işlerinden dışlamaktı.'),
  ('1870\'te Fransız-Prusya Savaşı\'na yol açan diplomatik krizin konusu neydi?', 'Bir Hohenzollern prensinin İspanya tahtına aday gösterilmesi', ['Belçika\'nın Prusya\'ya katılması', 'Lüksemburg\'un satılması ve Hollanda kralının tahttan çekilmesi', 'Roma\'nın İtalya\'ya verilmesi'], 'Leopold von Hohenzollern-Sigmaringen\'in adaylığı Fransa\'yı iki Hohenzollern devleti arasında kalma kaygısına düşürdü.'),
  ('Bismarck\'ın Fransa\'yı saldırgan konumuna düşürmek istemesinin güney Alman devletleri açısından önemi nedir?', 'Savunma antlaşmaları gereği güney devletlerinin Prusya\'nın yanında savaşa girmesi', ['Güney devletlerinin Fransa\'ya katılması', 'Güney devletlerinin savaşta tarafsız kalması', 'Güney devletlerinin Avusturya\'ya bağlanması'], 'Bavyera, Baden ve Württemberg ile yapılan gizli savunma antlaşmaları, Fransa saldırgan görününce işledi ve bütün Almanya ortak bir ulusal savaşa girdi.'),
  ('1871 Frankfurt Antlaşması\'yla Fransa\'nın Almanya\'ya ödemeyi kabul ettiği savaş tazminatı ne kadardı?', '5 milyar frank', ['50 milyon frank', '500 milyon frank', '50 milyar frank'], 'Fransa 5 milyar frangı 1873\'e kadar, beklenenden önce ödedi ve Alman işgal kuvvetleri ülkeden çekildi.'),
  ('1871 Frankfurt Antlaşması\'nın Fransa-Almanya ilişkileri üzerindeki uzun vadeli etkisi hangisidir?', 'Alsas-Loren\'in kaybı nedeniyle Fransa\'da kalıcı bir intikam duygusunun doğması', ['İki ülkenin hemen kalıcı bir ittifak kurması', 'Fransa\'nın Almanya\'ya ilhak edilmesi', 'Almanya\'nın Fransa\'ya toprak vermesi'], 'Fransız kamuoyunda \'revanşizm\' güçlendi; Strazburg heykeli Paris\'te kara tülle örtüldü. Bu düşmanlık Bismarck\'ın Fransa\'yı yalnız bırakma politikasını da belirledi.'),
  ('Mart 1871\'de Paris Komünü ayaklanmasını doğrudan başlatan olay hangisidir?', 'Hükümetin Ulusal Muhafız\'ın Montmartre\'daki toplarını almaya çalışması', ['Prusya ordusunun Paris\'i bombalaması', 'III. Napolyon\'un Paris\'e dönmesi', 'Kralın tahta çıkması'], 'Thiers hükümeti 18 Mart 1871\'de topları toplamak için asker gönderdi; halk ve Ulusal Muhafız direndi, hükümet Versay\'a çekildi.'),
  ('1871 sonrasında Fransa\'da monarşistlerin meclis çoğunluğuna sahip olmalarına rağmen krallığı geri getirememelerinin başlıca nedeni hangisidir?', 'Taht adayı Chambord Kontu\'nun üç renkli bayrağı reddedip beyaz bayrakta direnmesi', ['Bütün monarşistlerin cumhuriyete katılması', 'Almanya\'nın monarşiyi yasaklaması', 'Kral adayı olmaması'], 'Chambord Kontu Bourbon beyaz bayrağından vazgeçmedi; monarşistler Orléanist ve Bourbon yanlıları olarak bölündü ve cumhuriyet zamanla kalıcılaştı.'),
  ('Jules Ferry\'nin eğitim yasalarının cumhuriyetçiler açısından siyasi amacı neydi?', 'Kilisenin etkisini azaltıp cumhuriyete bağlı yurttaşlar yetiştirmek', ['Okulları tamamen Kilise\'ye devretmek', 'Eğitimi yalnız zenginlere ayırmak', 'Okullarda Almanca öğretmek'], 'Köy öğretmenleri (\'cumhuriyetin kara hüsarları\') cumhuriyetçi ve ulusal değerleri yaymanın aracı olarak görüldü.'),
  ('Émile Zola\'nın 1898\'de \'Suçluyorum!\' (J\'accuse...!) başlıklı açık mektubunu kime hitaben yazmıştır?', 'Fransa Cumhurbaşkanı\'na', ['Alman imparatoruna', 'Papaya', 'Dreyfus\'un ailesine ve avukatlarına'], 'Zola, L\'Aurore gazetesinde Cumhurbaşkanı Félix Faure\'a hitaben ordunun üst düzey yöneticilerini gerçeği örtbas etmekle suçladı; bu yüzden yargılanıp İngiltere\'ye kaçtı.'),
  ('Dreyfus olayının Fransız toplumunu ikiye bölmesi, hangi iki kesim arasındaki çatışmayı yansıtır?', 'Ordu, Kilise ve milliyetçi sağ ile cumhuriyetçi, laik ve hak savunucusu çevreler', ['Kraliyetçiler ile Bonapartçılar', 'Paris ile taşra belediyeleri', 'İngiltere yanlıları ile Rusya yanlıları'], 'Dreyfus karşıtları ordunun onurunu ve ulusal birliği öne çıkardı; Dreyfusçular bireysel hakları ve adaleti savundu. Olay Fransız siyasetini uzun süre şekillendirdi.'),
  ('Dreyfus davasını gazeteci olarak izleyen ve antisemitizmin Fransa\'da bile güçlü olmasından etkilenerek siyasi Siyonizm\'in kurucusu olan kişi kimdir?', 'Theodor Herzl', ['Max Nordau', 'Chaim Weizmann', 'Moses Hess'], 'Herzl 1896\'da \'Yahudi Devleti\' adlı kitabını yayımladı ve 1897\'de Basel\'de ilk Siyonist Kongre\'yi topladı.'),
  ('Fransa\'da 1905\'te kabul edilen ve devlet ile Kilise\'yi birbirinden ayıran yasanın sonucu hangisidir?', 'Devletin hiçbir dini tanımaması ve din adamlarına maaş ödememesi', ['Katolikliğin resmî devlet dini ilan edilmesi', 'Papanın Fransız piskoposlarını atama yetkisini yitirmesi ve devletin onları ataması', 'Protestan kiliselerinin kapatılması'], '1905 yasası 1801 Konkordatosu\'nu sona erdirdi; laiklik (laïcité) Fransız cumhuriyetinin temel ilkelerinden biri oldu.'),
  ('Panama Kanalı şirketinin iflası ve milletvekillerine rüşvet verildiğinin ortaya çıkmasıyla 1890\'ların başında Fransız cumhuriyetini sarsan olaya ne ad verilir?', 'Panama Skandalı', ['Dreyfus Olayı', 'Wilson Skandalı', 'Boulanger Krizi'], 'Lesseps\'in Panama girişimi çöktü; şirketin kredi almak için parlamenterleri satın aldığı ortaya çıktı ve skandal antisemit ve antiparlamenter akımları güçlendirdi.'),
  ('Bismarck\'ın Kulturkampf sırasında söylediği \'Canossa\'ya gitmeyeceğiz\' sözü hangi tarihsel olaya gönderme yapar?', 'Bir imparatorun papadan af dilemek zorunda kalmasına', ['Napolyon\'un papayı tutuklatıp Fontainebleau\'da gözaltına almasına', 'Luther\'in aforoz edilmesine', 'Haçlı seferlerinin başlamasına'], '1077\'de IV. Heinrich\'in Canossa\'da papadan af dilemesine gönderme yapan Bismarck, devletin Kilise karşısında boyun eğmeyeceğini vurguladı.'),
  ('Kulturkampf\'ın Bismarck açısından beklenmedik sonucu hangisidir?', 'Katolik Merkez Partisi\'nin seçimlerde güçlenmesi', ['Katoliklerin topluca Protestanlığa geçip Merkez Partisi\'ni dağıtması', 'Papalığın Almanya\'ya taşınması', 'Prusya\'nın Avusturya\'ya katılması'], 'Baskı Katolikleri Merkez Partisi etrafında birleştirdi. Bismarck 1878\'den sonra sosyalistlere karşı Merkez\'in desteğine ihtiyaç duyunca Kulturkampf yasalarının çoğunu yumuşattı.'),
  ('Bismarck\'ın 1878\'de sosyalist örgütleri, toplantıları ve yayınları yasaklayan yasayı çıkarmasına bahane olan olay hangisidir?', 'İmparator I. Wilhelm\'e yapılan iki suikast girişimi', ['Paris Komünü\'nün Berlin\'e yayılıp işçilerin ayaklanması', 'Bir Fransız saldırısı', 'Reichstag binasının yanması'], 'Suikast girişimlerinin sosyalistlerle doğrudan bağı kanıtlanmamıştı; ancak Bismarck bunları kullanarak Anti-Sosyalist Yasa\'yı kabul ettirdi. Yasa 1890\'a kadar yenilendi.'),
  ('Bismarck\'ın 1880\'lerde hastalık, iş kazası ve yaşlılık sigortalarını getirmesinin siyasi amacı neydi?', 'İşçileri sosyalist hareketten uzaklaştırıp devlete bağlamak', ['Sosyalist partiyi iktidara getirmek', 'İşverenleri tamamen devletleştirmek', 'Almanya\'yı tarım toplumuna döndürmek'], 'Bu \'havuç ve sopa\' politikasında sopa Anti-Sosyalist Yasa, havuç ise sosyal sigortaydı; Almanya modern sosyal güvenliğin öncüsü oldu.'),
  ('Bismarck döneminde getirilen sosyal sigortaların kronolojik sırası hangisidir?', 'Hastalık (1883), kaza (1884), yaşlılık ve malullük (1889)', ['Yaşlılık (1883), hastalık (1884), kaza (1889)', 'Kaza (1883), yaşlılık (1884), hastalık (1889)', 'Hastalık (1889), kaza (1884), yaşlılık (1883)'], 'Önce 1883 hastalık sigortası, ardından 1884 iş kazası sigortası ve son olarak 1889 yaşlılık-malullük sigortası çıkarıldı.'),
  ('Bismarck\'ın 1878 Berlin Kongresi\'nde üstlendiği rolü anlatmak için kendisi için kullandığı ifade hangisidir?', 'Dürüst simsar', ['Demir şansölye', 'Avrupa\'nın jandarması', 'Hasta adam'], 'Bismarck Almanya\'nın Balkanlarda doğrudan çıkarı olmadığını söyleyerek arabulucu rolü üstlendi; ancak Rusya kongre sonuçlarından hoşnut kalmadı.'),
  ('Bismarck\'ın 1887\'de Rusya ile imzaladığı ve iki devletin birbirine karşı savaşmamasını büyük ölçüde güvenceye alan gizli antlaşma hangisidir?', 'Reasürans Antlaşması', ['İkili İttifak', 'Üç İmparator Ligi', 'Alvensleben Sözleşmesi'], 'Rückversicherungsvertrag, Almanya\'nın hem Avusturya hem Rusya ile bağını korumasına yaradı; 1890\'da yenilenmedi.'),
  ('Reasürans Antlaşması\'nın 1890\'da yenilenmemesinin uzun vadeli sonucu hangisidir?', 'Rusya\'nın Fransa ile yakınlaşarak 1894\'te ittifak kurması', ['Rusya\'nın Üçlü İttifak\'a katılması', 'Fransa\'nın Almanya ile ittifak yapıp Alsas-Loren\'i geri alması', 'Avusturya\'nın Almanya\'dan ayrılması'], 'Bismarck\'ın düşüşünden sonra yenilenmeyen antlaşma, Fransa\'nın aradığı müttefiki bulmasına yol açtı; Almanya iki cepheli savaş tehlikesiyle karşı karşıya kaldı.'),
  ('Almanya\'da 1888 yılının \'Üç İmparator Yılı\' diye anılmasının nedeni nedir?', 'Aynı yıl içinde iki imparatorun ölüp üçüncüsünün tahta geçmesi', ['Üç imparatorun Berlin\'de bir araya gelmesi', 'Almanya\'nın üç imparatorluğa bölünmesi', 'Üç imparatorluğun Almanya\'ya savaş açması'], 'I. Wilhelm Mart 1888\'de öldü; oğlu III. Friedrich yalnız 99 gün hüküm sürdü; Haziran\'da II. Wilhelm tahta çıktı.'),
  ('Bismarck\'ın dış politikası ile II. Wilhelm\'in \'Weltpolitik\'i karşılaştırıldığında hangi fark öne çıkar?', 'Bismarck\'ın kıtasal dengeyi korumaya, Wilhelm\'in ise küresel genişlemeye yönelmesi', ['Bismarck\'ın büyük bir donanma kurması, Wilhelm\'in donanmayı dağıtması', 'İkisinin de Fransa ile ittifak kurması', 'Bismarck\'ın sömürge yarışını başlatıp Wilhelm\'in sona erdirmesi'], 'Bismarck Almanya\'yı tatmin olmuş bir güç olarak sunarken Wilhelm dönemi Almanya\'sı İngiltere ve Rusya ile ilişkileri gerdi ve ittifak sistemi yalnızlaştı.'),
  ('1867 Uzlaşması\'ndan sonra Avusturya ve Macaristan\'ın ortak yürüttüğü alanlar hangileridir?', 'Dış işleri, savunma ve bunların maliyesi', ['Eğitim, din işleri ve tarım', 'Yerel yönetim, polis ve adalet', 'Bütün iç işleri ile gümrükler ve demiryolları'], 'İki devletin ortak hükümdarı ve üç ortak bakanlığı (dışişleri, savaş, ortak maliye) vardı; diğer işler ayrı yönetiliyordu.'),
  ('Macar tarafında 1867 Uzlaşması\'nın mimarı sayılan ve \'ülkenin bilgesi\' diye anılan devlet adamı kimdir?', 'Ferenc Deák', ['Lajos Kossuth', 'István Széchenyi', 'Sándor Petőfi'], 'Deák, 1848 yasalarına dayanan ılımlı bir uzlaşma yolunu savundu. Sürgündeki Kossuth ise Uzlaşma\'yı Macar bağımsızlığına ihanet saydı.'),
  ('1867 Uzlaşması\'nın imparatorluktaki Slav halkları açısından sonucu hangisidir?', 'Haklarının Almanlar ve Macarlar karşısında ikinci planda kalması', ['Slavların da üçüncü eşit ortak olarak tanınması', 'Slavların bağımsız devletler kurması', 'Slavların Rusya\'ya bağlanması'], 'Uzlaşma iki egemen ulusa dayanıyordu; Çekler, Hırvatlar, Slovaklar, Rumenler ve diğerleri bu düzenden hoşnut olmadı ve ulusal gerginlikler sürdü.'),
  ('I. Nikola döneminde Rus eğitim bakanı Uvarov\'un ortaya koyduğu \'Resmî Milliyetçilik\' öğretisinin üç ilkesi hangileridir?', 'Ortodoksluk, otokrasi ve milliyet', ['Ekmek, toprak ve barış', 'Özgürlük, eşitlik ve kardeşlik ile insan hakları', 'Birlik, adalet ve özgürlük'], 'Bu üçlü, Batı\'dan gelen liberal ve devrimci fikirlere karşı Rus devletinin ideolojik temeli olarak sunuldu.'),
  ('II. Aleksandr\'ın serfliği kaldırmaya karar vermesinde en etkili olan gelişme hangisidir?', 'Kırım Savaşı yenilgisinin Rusya\'nın geri kalmışlığını göstermesi', ['Fransız Devrimi\'nin Rusya\'ya yayılıp çarı tahttan indirmesi', 'Napolyon\'un Rusya\'yı işgal etmesi', 'Rusya\'nın sanayileşmesini tamamlaması'], 'Kırım\'daki yenilgi ordunun, ekonominin ve ulaşımın Batı\'nın gerisinde kaldığını gösterdi; çar \'serfliği aşağıdan kaldırılmadan önce yukarıdan kaldırmak\' gerektiğini söyledi.'),
  ('1861\'de özgürlüğüne kavuşan Rus köylülerinin karşılaştığı temel sorun hangisidir?', 'Aldıkları toprak için uzun yıllar borç ödemek zorunda kalmaları', ['Hiçbir toprak almadan kentlere sürülmeleri', 'Askerlikten tamamen muaf tutulmaları', 'Soylu unvanı almaları'], 'Köylüler toprağı devlet kredisiyle satın aldı ve 49 yıl sürecek \'itfa ödemeleri\' yükümlülüğüne girdi; topraklar çoğunlukla köy topluluğuna (mir) verildi.'),
  ('1870\'lerde Rus üniversite öğrencilerinin köylere giderek köylüleri devrime kazanmaya çalıştığı harekete ne ad verilir?', 'Halka doğru gitmek (Narodnizm)', ['Dekabrizm', 'Slavofillik (Rus özcülüğü)', 'Bolşevizm'], 'Narodnikler köy topluluğunu sosyalizmin temeli sayıyordu; ancak köylüler onları çoğu kez polise teslim etti ve hareket başarısız oldu.'),
  ('Çar II. Aleksandr\'ı 1881\'de bombalı saldırıyla öldüren devrimci örgüt hangisidir?', 'Narodnaya Volya', ['Kara Yüzler', 'Bolşevik Parti', 'Zemlya i Volya\'nın Kara Paylaşım kolu'], 'II. Aleksandr, Petersburg\'da arabasına atılan bombalarla öldürüldü. Halefi III. Aleksandr reformları geri çevirip baskı politikası izledi.'),
  ('Rusya\'nın 19. yüzyıldaki reform ve tepki dönemlerinin değişimi (I. Nikola, II. Aleksandr, III. Aleksandr) hangi sırayla verilmiştir?', 'Baskı, reform, yeniden baskı', ['Reform, baskı, reform', 'Baskı, baskı, reform', 'Baskı, baskı, yeniden reform'], 'I. Nikola sert bir baskı rejimi kurdu, II. Aleksandr Büyük Reformları yaptı, III. Aleksandr ise babasının öldürülmesinden sonra tepkici bir yola döndü.'),
  ('İngiltere\'de 1832 Reform Yasası\'nın kaldırdığı, çok az seçmeni olduğu hâlde parlamentoya milletvekili gönderen seçim bölgelerine ne ad verilir?', 'Çürük kasabalar', ['Serbest kentler ve kraliyet beratlı yerleşimler', 'Kontluklar', 'Ruhani bölgeler'], 'Old Sarum gibi neredeyse ıssız yerler milletvekili seçerken Manchester gibi büyük sanayi kentlerinin temsilcisi yoktu. 1832 yasası bu dengesizliği kısmen giderdi.'),
  ('1832 Reform Yasası\'nın oy hakkını genişlettiği esas kesim hangisidir?', 'Kentli orta sınıf', ['Bütün yetişkin erkekler', 'Kadınlar', 'Sanayi işçileri ve tarım emekçileri'], 'Yasa seçmen sayısını artırdı ama oy hakkı hâlâ mülkiyete bağlıydı; işçiler dışarıda kaldı ve bu durum Çartist hareketi doğurdu.'),
  ('1815\'te çıkarılan ve yabancı tahılın ithalatını yüksek gümrüklerle kısıtlayan İngiliz yasaları hangi kesimin çıkarını koruyordu?', 'Büyük toprak sahipleri', ['Fabrika işçileri', 'Sanayici ihracatçılar', 'Kentli tüketiciler ve dükkân sahipleri'], 'Tahıl Yasaları (Corn Laws) ekmeği pahalılaştırdı; sanayiciler ve işçiler bu yasaları toprak aristokrasisinin ayrıcalığı olarak gördü.'),
  ('Tahıl Yasaları\'nın kaldırılması için Richard Cobden ve John Bright\'ın önderliğinde kurulan örgüt hangisidir?', 'Tahıl Yasası Karşıtı Birlik', ['Fabian Derneği', 'Primrose Ligi', 'Çartist Ulusal Konvansiyonu'], 'Manchester merkezli Anti-Corn Law League serbest ticaretin en etkili savunucusu oldu; 1846\'da hedefine ulaştı.'),
  ('Gladstone\'un İrlanda için önerdiği \'Home Rule\' tasarıları neyi amaçlıyordu?', 'İrlanda\'ya kendi iç işleri için ayrı bir parlamento vermek', ['İrlanda\'yı tamamen bağımsız bir cumhuriyet yapmak', 'İrlanda\'yı İskoçya\'ya bağlamak', 'İrlanda\'da Katolikliği yasaklamak'], 'Home Rule, Birleşik Krallık içinde kalarak İrlanda\'ya bir yasama meclisi vermeyi öngörüyordu; Liberal Parti bu konuda bölündü.'),
  ('İngiltere\'de 1834 Yoksullar Yasası\'nın yardımı nasıl düzenlediği bilinir?', 'Yardım almak isteyen yoksulların ağır koşullu iş evlerine girmesini şart koşarak', ['Bütün yoksullara koşulsuz düzenli maaş bağlayarak', 'Yoksul yardımını tamamen kilise vakıflarına bırakarak', 'Yoksulları sömürgelere zorla göndererek'], 'Yeni Yoksullar Yasası, iş evlerindeki koşulları bilerek ağır tuttu ki insanlar ancak çaresiz kalınca başvursun; Dickens\'ın \'Oliver Twist\'i bu düzeni eleştirir.'),
  ('İngiltere\'de 1829\'da çıkarılan ve Katoliklerin parlamentoya girmesinin önünü açan yasa hangi adla bilinir?', 'Katoliklerin Özgürleştirilmesi', ['Test Yasası', 'Hoşgörü Yasası', 'Veraset Yasası'], 'İrlandalı lider Daniel O\'Connell\'ın seçimi kazanması üzerine Wellington hükümeti, Katoliklere siyasi haklar tanıyan yasayı çıkardı.'),
  ('İngiltere\'nin 19. yüzyılda kıta Avrupası\'ndaki gibi büyük devrimler yaşamamasının nedenlerinden biri aşağıdakilerden hangisidir?', 'Kademeli reformlarla yeni kesimlerin siyasi sisteme katılması', ['Hiçbir toplumsal sorunun bulunmaması', 'Bütün halka 1815\'te oy hakkı verilmiş olması', 'Parlamentonun tamamen kaldırılmış olması'], '1832, 1867 ve 1884 reform yasaları ile Tahıl Yasaları\'nın kaldırılması gibi adımlar baskıyı azalttı; böylece sistem devrimsiz biçimde genişledi.'),
  ('İngiltere\'de 1830\'lardaki fabrika yasalarının en önemli düzenlemesi hangisidir?', 'Çocukların fabrikalarda çalışma yaşının ve saatlerinin sınırlandırılması', ['Grevlerin serbest bırakılıp sendikalara maaş bağlanması', 'Kadınlara oy hakkı tanınması', 'Fabrikaların devletleştirilmesi'], '1833 Fabrika Yasası dokuma fabrikalarında dokuz yaşından küçüklerin çalışmasını yasakladı ve çocukların çalışma saatlerini sınırladı; uygulamayı denetleyecek müfettişler atandı.'),
  ('1870\'lerde İngiliz işçilerine oy hakkının genişletilmesine paralel olarak getirilen gizli oy (1872) uygulamasının amacı neydi?', 'Seçmenlerin işverenlerin ve toprak sahiplerinin baskısından korunması', ['Oy kullanmayı zorunlu hâle getirmek', 'Seçimleri tamamen kaldırmak', 'Yalnız soylulara oy hakkı vermek'], 'Açık oylamada kiracılar ve işçiler oylarını patronlarının istediği yönde kullanmaya zorlanabiliyordu; gizli oy bu baskıyı azalttı.'),
  ('Burke\'e yanıt olarak \'İnsan Hakları\' (Rights of Man) adlı eseri yazan ve Fransız Ulusal Konvansiyonu\'na üye seçilen düşünür kimdir?', 'Thomas Paine', ['William Godwin', 'Jean-Jacques Rousseau', 'Mary Wollstonecraft'], 'Paine hem Amerikan hem Fransız devrimlerini savundu; Konvansiyon\'da kralın idamına karşı çıktığı için Terör döneminde hapsedildi.'),
  ('Edmund Burke\'ün Fransız Devrimi eleştirisinin özü aşağıdakilerden hangisidir?', 'Köklü kurumları soyut akıl adına bir anda yıkmanın tehlikeli olduğu', ['Krallığın derhâl kaldırılması gerektiği', 'Mülkiyetin kaldırılması gerektiği', 'Devrimin yeterince radikal olmadığı'], 'Burke yavaş ve tarihsel deneyime dayalı değişimi savundu; devrimin yıkıcı ve şiddetli bir yola gireceğini 1790\'da, Terör\'den önce öngördü.'),
  ('19. yüzyıl başında liberalizmin temel talepleri arasında aşağıdakilerden hangisi yer almaz?', 'Kilise ve soyluların ayrıcalıklarının korunması', ['Anayasa ile sınırlı yönetim ve kuvvetler ayrılığı', 'Basın ve düşünce özgürlüğü', 'Yasa önünde eşitlik'], 'Liberaller anayasal yönetim, bireysel haklar ve serbest piyasayı savundu; ancak çoğu genel oy yerine mülkiyete dayalı seçme hakkından yanaydı.'),
  ('1815-1848 döneminde liberallerin büyük bölümünün genel oy hakkına mesafeli durmasının nedeni nedir?', 'Siyasi katılımı eğitimli ve mülk sahibi kesimle sınırlamak istemeleri', ['Mutlak monarşiyi savunmaları', 'Mülkiyetin kaldırılmasını istemeleri', 'Kadınlara oy hakkı vermeyi öncelemeleri'], 'Klasik liberaller \'kalabalığın tiranlığından\' çekiniyordu; oy hakkını vergi ve mülkiyete bağlayan sistemleri savundular.'),
  ('Toplumun \'falanster\' adı verilen ortak yaşam birimlerinde örgütlenmesini öneren Fransız ütopyacı sosyalist kimdir?', 'Charles Fourier', ['Saint-Simon', 'Pierre-Joseph Proudhon', 'Louis Blanc'], 'Fourier, yaklaşık 1600 kişilik falansterlerde işin insanların eğilimlerine göre paylaşılacağı uyumlu bir toplum hayal etti.'),
  ('Sanayiciler, bilim insanları ve mühendislerin yönettiği akılcı bir sanayi toplumu fikrini savunan ve izleyicileri Süveyş Kanalı gibi projeleri destekleyen Fransız düşünür kimdir?', 'Saint-Simon', ['Auguste Comte', 'Charles Fourier', 'Alexis de Tocqueville'], 'Saint-Simoncular bankacılık, demiryolu ve kanal girişimlerinde etkili oldu; Lesseps\'in Süveyş projesi de bu çevreden destek gördü.'),
  ('\'Mülkiyet nedir? Mülkiyet hırsızlıktır\' sözüyle tanınan ve anarşizmin kurucularından sayılan Fransız düşünür kimdir?', 'Pierre-Joseph Proudhon', ['Mihail Bakunin', 'Pyotr Alekseyeviç Kropotkin', 'Auguste Blanqui'], 'Proudhon 1840\'taki eserinde bu sözü kullandı; devletin yerine üreticilerin gönüllü federasyonunu öneren \'karşılıkçılık\' (mutualizm) düşüncesini geliştirdi.'),
  ('Uluslararası İşçi Derneği (Birinci Enternasyonal) hangi yıl ve nerede kurulmuştur?', '1864, Londra', ['1848, Paris', '1889, Paris', '1871, Berlin'], 'Birinci Enternasyonal 1864\'te Londra\'da kuruldu; Paris Komünü sonrasındaki ayrılıklarla zayıfladı ve 1876\'da dağıldı.'),
  ('Grimm Kardeşler\'in Alman halk masallarını derlemesi 19. yüzyıl ulusçuluğu bakımından neden önemlidir?', 'Halk kültürünü ulusal kimliğin kaynağı olarak öne çıkarması', ['Masalları Fransızcaya çevirip yayması', 'Alman dilini sadeleştirip Latinceye yaklaştırması', 'Masalların tamamını kendilerinin uydurması'], 'Romantik dönemde halk masalları, şarkıları ve dil, bir ulusun \'özünü\' taşıyan miras olarak görüldü; Grimmler Alman sözlüğü üzerinde de çalıştı.'),
  ('Fransız düşünür Ernest Renan\'ın 1882\'deki \'Ulus nedir?\' konferansında ulusu tanımlamak için kullandığı ünlü benzetme hangisidir?', 'Her gün yinelenen bir halkoylaması', ['Kan ve toprak birliği', 'Tek bir dinin topluluğu', 'Bir hanedanın mülkü'], 'Renan ulusu ırk, dil ya da dinle değil, ortak geçmiş ve birlikte yaşama isteğiyle tanımladı; bu yaklaşım öznel ya da siyasi ulus anlayışının klasik metnidir.'),
  ('Delacroix\'nın 1824\'te sergilediği \'Sakız Katliamı\' tablosu hangi siyasi davaya duyulan sempatiyi yansıtır?', 'Yunan bağımsızlık mücadelesi', ['Polonya Kasım Ayaklanması', 'İtalyan birliği', 'Belçika ayaklanması'], 'Tablo 1822\'de Sakız Adası\'ndaki olayları konu alır ve Avrupa\'da Filhelen duyguların güçlenmesine katkıda bulundu.'),
  ('Romantizm akımının Aydınlanma\'ya göre farklılaşan yönü aşağıdakilerden hangisidir?', 'Duygu, gelenek ve ulusal geçmişe yönelmesi', ['Evrensel akla ve bilimsel yönteme dayanması', 'Klasik Yunan kurallarına bağlı kalması', 'Dini tamamen reddetmesi'], 'Romantikler Aydınlanma\'nın evrensel akılcılığına karşı duyguyu, bireysel deneyimi ve halkların özgün tarihini öne çıkardı; bu yönelim ulusçuluğu besledi.'),
  ('19. yüzyılda pek çok Avrupa ulusunda ulusal tarihlerin yazılması, sözlüklerin hazırlanması ve ulusal müzelerin kurulmasının ortak işlevi nedir?', 'Ortak bir ulusal geçmiş ve kimlik bilinci oluşturmak', ['Ulusal dilleri ortadan kaldırmak', 'İmparatorlukları güçlendirmek', 'Latinceyi yeniden ortak dil yapmak'], 'Tarihçiler, dilciler ve sanatçılar \'ulusal uyanış\' sürecinde kültürel bir zemin hazırladı; siyasi talepler çoğu kez bu kültürel evreyi izledi.'),
  ('Alman ulusçuluğunun 1840 Ren krizinde yükselişini yansıtan \'Ren\'de Nöbet\' şarkısı hangi ülkeye karşı duyulan tepkiyi dile getirir?', 'Fransa', ['Rusya', 'Avusturya', 'Danimarka'], '1840\'ta Fransız hükümetinin Ren\'i doğal sınır olarak talep etmesi Almanya\'da büyük tepki yarattı; \'Die Wacht am Rhein\' 1870 savaşında da çok söylendi.'),
  ('Polonya\'nın ulusal şairi sayılan ve \'Pan Tadeusz\' destanını sürgünde yazan kişi kimdir?', 'Adam Mickiewicz', ['Henryk Sienkiewicz', 'Juliusz Słowacki', 'Frédéric Chopin'], 'Mickiewicz, Polonya\'nın paylaşılmasının ardından ulusal kimliği edebiyatla yaşattı; 1834\'te Paris\'te yayımlanan Pan Tadeusz Litvanya\'daki Polonya soylu yaşamını anlatır.'),
  ('19. yüzyılda okulların, zorunlu askerliğin ve demiryollarının ulus devletler açısından ortak işlevi nedir?', 'Farklı bölgelerden insanları ortak bir dil ve kimlik etrafında birleştirmek', ['Bölgesel dilleri ve kimlikleri güçlendirmek', 'İnsanların yerel kalmasını sağlamak', 'Uluslararası göçü engellemek'], 'Eugen Weber\'in \'Köylülerden Fransızlara\' tezinde anlatıldığı gibi, okul, ordu ve ulaşım ağları yerel kimlikleri ulusal kimlikle bütünleştirdi.'),
  ('Fransız Devrimi\'nin ulus anlayışı bakımından getirdiği yenilik aşağıdakilerden hangisidir?', 'Egemenliğin hükümdardan yurttaşlar topluluğu olan ulusa geçmesi', ['Ulusun bir hanedanın mülkü sayılması', 'Ulusun yalnız soylulardan oluştuğunun kabulü', 'Ulusun dinle özdeşleştirilmesi'], '1789 bildirisi \'Bütün egemenliğin ilkesi esas olarak ulustadır\' der. Böylece ulus, yasa yapma hakkına sahip yurttaşlar topluluğu olarak tanımlandı.'),
  ('Eflak ve Boğdan meclislerinin 1859\'da aynı kişiyi bey seçerek iki beyliğin fiilen birleşmesini sağladığı kişi kimdir?', 'Alexandru Ioan Cuza', ['I. Carol', 'Mihail Kogălniceanu', 'Nicolae Bălcescu'], 'Büyük güçler iki beyliğin ayrı kalmasını öngörmüştü; ancak her iki meclisin Cuza\'yı seçmesi bu kuralı dolanarak Romanya\'nın temelini attı.'),
  ('III. Napolyon\'un 1867\'de Hollanda kralından satın almaya çalıştığı ve krizin bir Londra konferansıyla tarafsızlık statüsüyle çözüldüğü ülke hangisidir?', 'Lüksemburg', ['Belçika', 'Monako', 'Andorra'], 'Lüksemburg krizi Fransa ile Prusya arasındaki gerilimi artırdı; 1867 Londra Antlaşması Lüksemburg\'u tarafsız ilan etti ve Prusya garnizonu çekildi.'),
  ('Fransız Devrimi döneminde \'kardeş cumhuriyet\' olarak Hollanda\'da kurulan devlet hangisidir?', 'Batav Cumhuriyeti', ['Helvetya Cumhuriyeti', 'Partenopean Cumhuriyeti', 'Liguria Cumhuriyeti'], 'Batav Cumhuriyeti 1795\'te Fransız ordularının desteğiyle kuruldu; 1806\'da Napolyon onu Louis Bonaparte\'ın yönettiği Hollanda Krallığı\'na dönüştürdü.'),
  ('Fransız Devrimi\'nin \'kardeş cumhuriyetler\' kurması, devrimin hangi yönünü gösterir?', 'İlkelerini silah zoruyla da olsa komşu ülkelere yayma eğilimini', ['Avrupa\'dan tamamen yalıtılmayı', 'Mutlak monarşileri desteklemeyi', 'Sömürgecilikten vazgeçmeyi'], 'Devrimci Fransa, \'saraylara savaş, kulübelere barış\' sloganıyla feodal düzeni yıkmayı vaat etti; ancak kardeş cumhuriyetler aslında Fransa\'nın uyduları oldu.'),
  ('Fransız Devrimi\'nin 1792\'de ilan ettiği \'Saraylara savaş, kulübelere barış!\' sloganı neyi ifade eder?', 'Savaşın halklara değil hükümdarlara ve ayrıcalıklılara karşı olduğunu', ['Fransa\'nın bütün savaşlardan çekildiğini', 'Kırsal kesime vergi konulacağını', 'Sarayların korunacağını'], 'Konvansiyon, Avrupa halklarını kendi hükümdarlarına karşı özgürlüğe çağıran bir dil benimsedi; Kasım 1792\'de özgürlük isteyen halklara yardım sözü verildi.'),
  ('1792 sonbaharında Fransız devrim ordusunun Avusturya Hollandası\'na (Belçika) girmesini sağlayan zafer hangisidir?', 'Jemappes', ['Valmy', 'Fleurus', 'Neerwinden'], 'Kasım 1792\'deki Jemappes zaferiyle Belçika işgal edildi; Fransa\'nın Antwerp\'e yaklaşması İngiltere\'yi kaygılandırarak savaşa girmesine katkıda bulundu.'),
  ('1789 bildirisinde \'Özgürlük, başkasına zarar vermeyen her şeyi yapabilmektir\' tanımının ardından özgürlüğün sınırlarını kimin belirleyeceği söylenir?', 'Yasanın', ['Kralın', 'Kilisenin', 'Soyluların'], 'Bildiri, doğal hakların sınırlarının yalnız yasa ile belirlenebileceğini ve yasanın genel iradenin ifadesi olduğunu ilan eder.'),
  ('Aydınlanmacı matematikçi ve Jiroden yanlısı olan, Terör döneminde saklanırken \'İnsan Zihninin İlerlemesinin Tarihsel Tablosu\'nu yazan ve tutuklandıktan sonra hücrede ölen düşünür kimdir?', 'Condorcet Markisi', ['Lavoisier', 'Volney', 'Destutt de Tracy'], 'Condorcet, ilerleme fikrinin ve kadınlara eşit hakların savunucusuydu; 1794\'te tutuklandıktan iki gün sonra hücresinde ölü bulundu.'),
  ('Talleyrand\'ın Devrim\'in başında Ruhban Sivil Anayasası\'na yemin eden birkaç piskopostan biri olması, onun siyasi kariyeri hakkında neyi gösterir?', 'Rejim değişikliklerine uyum sağlayarak hep iktidara yakın kalabilmesini', ['Hayatı boyunca kraliyetçi bir din adamı olarak kalmasını', 'Devrime baştan sona karşı çıkmasını', 'Napolyon\'a hiç hizmet etmemesini'], 'Talleyrand piskoposken devrimi destekledi, Direktuvar ve Napolyon\'un dışişleri bakanı oldu, sonra Bourbonlara ve Louis-Philippe\'e hizmet etti.'),
  ('Waterloo Savaşı\'nda Prusya ordusunu izlemekle görevlendirilen ancak savaş alanına yetişemeyen Fransız mareşal kimdir?', 'Emmanuel de Grouchy', ['Michel Ney', 'Nicolas Soult', 'Louis-Nicolas Davout'], 'Grouchy Wavre\'de Prusya artçısıyla oyalandı; Blücher\'in ana kuvvetinin Waterloo\'ya ulaşmasını engelleyemedi.'),
  ('Napolyon\'un yükselişi Fransız Devrimi\'nin mirası açısından nasıl değerlendirilebilir?', 'Eşitlik ve merkezî devleti korurken siyasi özgürlükleri kısıtladı', ['Devrimin bütün kazanımlarını ortadan kaldırıp feodaliteyi geri getirdi', 'Devrimin bütün siyasi özgürlüklerini genişletti', 'Devrimle hiçbir bağlantısı olmadan krallık kurdu'], 'Napolyon yasa önünde eşitliği, liyakati ve Kilise mallarının satışını korudu; ancak basın sansürü, plebisitler ve tek adam yönetimiyle siyasi özgürlükleri daralttı.'),
  ('Napolyon Kanunu\'nun Avrupa dışında da etkili olmasının nedeni hangisidir?', 'Açık, sistematik ve uygulanabilir bir medeni hukuk modeli sunması', ['Yalnızca Fransızca konuşan ülkelerde geçerli olması', 'Bir din kitabına dayanması', 'Krallara sınırsız yetki vermesi'], 'Kanun, Belçika, Hollanda, İtalya ve Latin Amerika\'dan Louisiana\'ya kadar pek çok hukuk sistemini etkiledi; Osmanlı\'daki bazı düzenlemeler de Fransız hukukundan yararlandı.'),
  ('Napolyon döneminin sonunda Fransa\'nın, 1792\'deki sınırlarına benzer sınırlara geri döndürülmesi hangi antlaşmalarla gerçekleşmiştir?', '1814 ve 1815 Paris antlaşmaları', ['Campo Formio ve Lunéville antlaşmaları', 'Tilsit ve Pressburg antlaşmaları', 'Westfalya ve Utrecht antlaşmaları'], 'Birinci Paris Antlaşması Fransa\'ya 1792 sınırlarını bıraktı; Yüz Gün\'den sonraki İkinci Paris Antlaşması sınırları biraz daha daralttı.'),
  ('Cavour ve Bismarck\'ın birlik politikalarındaki ortak yöntem hangisidir?', 'Büyük güçler arasındaki rekabeti kullanıp Avusturya\'yı yalnız bırakmak', ['Halk ayaklanmalarına önderlik edip cumhuriyet kurmak', 'Avusturya ile ittifak yaparak birlik sağlamak', 'Papalığın önderliğini kabul etmek'], 'Cavour Fransa\'yı, Bismarck ise önce Avusturya\'yı sonra Fransa\'yı kendi amaçları için kullandı; ikisi de Realpolitik\'in örnekleridir.'),
  ('Aşağıdaki olayların doğru kronolojik sıralaması hangisidir?', 'Valmy, Austerlitz, Leipzig, Waterloo', ['Austerlitz, Valmy, Waterloo, Leipzig', 'Valmy, Leipzig, Austerlitz, Waterloo', 'Leipzig, Austerlitz, Valmy, Waterloo'], 'Valmy 1792, Austerlitz 1805, Leipzig 1813, Waterloo 1815 yıllarında yapılmıştır.'),
  ('İtalyan birliğinin aşamaları kronolojik olarak hangi seçenekte doğru verilmiştir?', 'Lombardiya, Güney İtalya, Venedik, Roma', ['Roma, Venedik, Lombardiya, Güney İtalya', 'Venedik, Roma, Lombardiya, Güney İtalya', 'Güney İtalya, Roma, Lombardiya, Venedik'], 'Lombardiya 1859, Sicilya ve Napoli 1860, Venedik 1866, Roma 1870\'te İtalya\'ya katıldı.'),
  ('Bir öğrenci, 1815\'te kurulan düzenin 1870\'lere gelindiğinde büyük ölçüde değiştiğini savunuyor. Bu görüşü en iyi destekleyen gelişme hangisidir?', 'İtalya ve Almanya\'nın birleşik ulus devletler olarak ortaya çıkması', ['Avusturya\'nın İtalya\'daki bütün topraklarını koruması', 'Alman Konfederasyonu\'nun güçlenerek sürmesi', 'Fransa\'da Bourbonların tahta dönmesi'], 'Viyana düzeni dağınık bir Almanya ve İtalya öngörmüştü; 1871\'de ikisi de birleşmiş, Avrupa güç dengesi kökten değişmişti.'),
  ('Birleşik Almanya\'nın 1871\'de ortaya çıkmasının Avrupa güç dengesine etkisi en iyi hangi ifadeyle açıklanır?', 'Kıtanın merkezinde nüfus ve sanayice en güçlü devletin doğması', ['Fransa\'nın kıtanın en güçlü devleti olması', 'Avusturya\'nın Almanya\'yı yönetmesi', 'İngiltere\'nin kıtaya ilhak edilmesi'], 'İngiliz siyasetçi Disraeli, Alman birliğini \'Fransız Devrimi\'nden daha büyük bir siyasi olay\' diye niteledi; güç dengesinin bozulduğunu düşünüyordu.'),
  ('1830 ve 1848 devrimlerinin ikisinin de Paris\'te başlaması ve kısa sürede başka ülkelere yayılması neyi gösterir?', 'Fransa\'nın Avrupa\'da devrimci hareketlerin öncüsü olarak görüldüğünü', ['Paris\'in Avrupa\'dan yalıtılmış olduğunu', 'Devrimlerin yalnız kırsalda yaşandığını', 'Fransa\'nın devrimleri bastırdığını'], '1789 deneyimi nedeniyle Paris, liberal ve cumhuriyetçi hareketler için bir model ve işaret merkezi kabul edildi; Metternich \'Fransa nezle olunca Avrupa hapşırır\' sözünü kullanmıştır.'),
  ('1848\'de Frankfurt\'ta liberallerin başaramadığı Alman birliğinin 1871\'de Bismarck\'ın elinde gerçekleşmesi, birliğin karakteri hakkında neyi gösterir?', 'Birliğin liberal-parlamenter değil, Prusya\'nın askerî ve monarşik ağırlığı altında kurulduğunu', ['Birliğin bir halk devrimiyle kurulduğunu', 'Almanya\'nın cumhuriyet olarak doğduğunu', 'Avusturya\'nın birliğe önderlik ettiğini'], 'İmparatorluk, Prusya kralının imparator olduğu, ordunun ayrıcalıklı konumda bulunduğu ve parlamentonun sınırlı yetkiye sahip olduğu bir yapıydı.'),
  ('Napolyon\'un Austerlitz zaferi ile Waterloo yenilgisi arasında yaklaşık kaç yıl geçmiştir?', '10', ['5', '7', '12'], 'Austerlitz Aralık 1805\'te, Waterloo Haziran 1815\'te yapıldı; arada yaklaşık on yıl vardır.'),
  ('Bir belge \'Cumhuriyetin VIII. Yılı\' tarihini taşımaktadır. Bu belge en çok hangi olayla aynı dönemde yazılmış olabilir?', '18 Brumaire darbesi', ['Bastille\'in alınması', 'Kralın idamı', 'Napolyon\'un taç giymesi'], 'I. Yıl Eylül 1792\'de başladığına göre VIII. Yıl Eylül 1799-Eylül 1800 arasıdır; 18 Brumaire VIII (Kasım 1799) darbesi bu yıla düşer.'),
  ('1814-1848 arasında Fransa\'da tahta çıkan kralların sırası hangi seçenekte doğru verilmiştir?', 'XVIII. Louis, X. Charles, Louis-Philippe', ['X. Charles, XVIII. Louis, Louis-Philippe', 'Louis-Philippe, X. Charles, XVIII. Louis', 'XVIII. Louis, Louis-Philippe, X. Charles'], 'XVIII. Louis 1814/1815-1824, X. Charles 1824-1830, Louis-Philippe 1830-1848 arasında tahtta kaldı.'),
  ('Avrupa\'da 19. yüzyılda serflik ya da benzeri feodal yükümlülüklerin kaldırılmasını kronolojik sıraya koyan seçenek hangisidir?', 'Fransa (1789), Prusya (1807), Avusturya (1848), Rusya', ['Rusya, Avusturya, Prusya, Fransa', 'Prusya, Fransa, Rusya, Avusturya', 'Avusturya, Rusya, Fransa, Prusya'], 'Fransa 4 Ağustos 1789 kararlarıyla, Prusya 1807 Ekim Fermanı ile, Avusturya 1848\'de, Rusya ise 1861\'de serfliği kaldırdı.'),
  ('1848\'de İtalya\'da Avusturya ordusunu yöneten ve adına Johann Strauss\'un bir marş bestelediği yaşlı mareşal kimdir?', 'Joseph Radetzky', ['Alfred Windischgrätz', 'Ludwig von Benedek', 'Arşidük Karl'], 'Radetzky Custoza (1848) ve Novara (1849) zaferleriyle Lombardiya-Venedik\'i Avusturya için korudu; \'Radetzky Marşı\' bugün de Viyana\'nın yılbaşı konserinde çalınır.'),
  ('Trafalgar zaferinin Napolyon savaşlarının gidişatındaki stratejik önemi hangisidir?', 'Napolyon\'un İngiltere\'yi işgal etme olasılığının ortadan kalkması', ['Napolyon\'un Rusya\'yı fethetmesinin önünün açılması', 'Fransız donanmasının Akdeniz\'e egemen olması', 'İspanya\'nın İngiltere\'ye savaş açması'], 'İngiliz deniz üstünlüğü yüzyıl boyunca tartışmasız kaldı; Napolyon karada kazandığı zaferlere karşın İngiltere\'yi doğrudan vuramadı.'),
  ('1867 Uzlaşması\'ndan sonra Franz Joseph\'in Budapeşte\'de Macaristan kralı olarak taç giymesi neyi simgeler?', 'Macar devletinin ve anayasasının Habsburg hanedanınca tanınmasını', ['Macaristan\'ın Avusturya\'ya tamamen ilhakını', 'Macaristan\'ın cumhuriyet olmasını', 'Habsburgların Macaristan\'dan çekilmesini'], '1848-1849\'da Macarlarla savaşan Franz Joseph\'in 1867\'de Macar kralı olarak taç giymesi, iki taraf arasındaki uzlaşmanın simgesiydi.'),
  ('1867 Uzlaşması\'ndan sonra Macaristan\'ın ilk başbakanı olan ve daha sonra Avusturya-Macaristan dışişleri bakanı olarak Berlin Kongresi\'ne katılan devlet adamı kimdir?', 'Gyula Andrássy', ['Ferenc Deák', 'Kálmán Tisza', 'István Tisza'], 'Andrássy 1848 devriminde yer aldığı için gıyabında idama mahkûm edilmişti; uzlaşma sonrasında imparatorluğun en etkili devlet adamlarından biri oldu.'),
  ('Fransız-Prusya Savaşı sırasında Paris kuşatmasının bir sonucu olarak kentte yaşanan sıkıntıyı en iyi anlatan durum hangisidir?', 'Kıtlık nedeniyle hayvanat bahçesindeki hayvanların bile yenmesi', ['Kentin hiçbir zaman kuşatılmaması', 'Kente bol miktarda erzak gelmesi', 'Kentin hemen teslim olması'], 'Eylül 1870-Ocak 1871 kuşatmasında Parisliler at, kedi, fare ve hayvanat bahçesindeki filleri yemek zorunda kaldı.'),
  ('Fransız Devrimi\'nden Alman birliğine kadar uzanan dönemde Fransa\'nın Avrupa\'daki konumundaki değişimi en iyi özetleyen ifade hangisidir?', 'Kıtanın baskın gücü olmaktan Almanya karşısında yalnız kalmaya geçiş', ['Sürekli büyüyerek bütün kıtanın tek ve rakipsiz egemeni olması', 'Avrupa siyasetinden tamamen çekilmesi', 'Almanya ile birleşip tek devlet olması'], 'Napolyon döneminde kıtanın çoğuna egemen olan Fransa, 1871\'de yenilmiş, toprak kaybetmiş ve Bismarck\'ın ittifak sistemiyle yalnızlaştırılmıştı.'),
  ('Bir 1848 bildirisinde \'Çalışma hakkı her yurttaşın hakkıdır; devlet iş bulamayanlara iş sağlamakla yükümlüdür\' deniyor. Bu talep o yıl Fransa\'da hangi uygulamaya dönüşmüştür?', 'Ulusal Atölyelerin kurulmasına', ['Konkordatonun imzalanmasına', 'Kıta Ablukası\'nın ilanına', 'Le Chapelier Yasası\'nın çıkarılmasına ve grevlerin yasaklanmasına'], 'Çalışma hakkı talebi, işsizlere iş vermek için kurulan Ulusal Atölyelerle karşılık buldu.'),
  ('1792\'de Fransa\'ya saldıran ordular kısa sürede Paris\'e yaklaşmış, ardından Valmy\'de durdurulmuştur. Bu gelişmelerin Fransa\'da siyasetin radikalleşmesi üzerindeki etkisi en iyi nasıl açıklanır?', 'Dış tehdit, kralın ihanet ettiği kanısını güçlendirip monarşinin yıkılmasını hızlandırdı', ['Dış tehdit kralın konumunu güçlendirip mutlakiyeti geri getirdi', 'Savaş tamamen sona erdiği için siyaset yatıştı', 'Savaş yalnız sömürgelerde sürdüğü için Paris etkilenmedi'], 'Savaş ve işgal korkusu, kralın düşmanla iş birliği yaptığı inancını yaydı; 10 Ağustos ve Eylül katliamları bu ortamda gerçekleşti.'),
  ('Terör döneminde \'Cumhuriyetin düşmanlarına özgürlük yoktur\' anlayışı savunulmuştur. Bu anlayışın devrimin kendi ilkeleriyle çelişen yanı hangisidir?', 'İnsan hakları bildirisindeki bireysel güvencelerin askıya alınması', ['Kiliseye eski ayrıcalıklarının geri verilmesi', 'Krala yeniden mutlak yetki verilip meclislerin tamamen kapatılması', 'Fransa\'nın tüm savaşlardan çekilmesi'], 'Devrim kişi özgürlüğünü ve adil yargılanmayı ilan etmişti; Terör döneminde şüpheliler yargısız ya da güvencesiz cezalandırıldı.'),
  ('Bir haritada Fransa\'nın doğrudan yönettiği topraklar, Napolyon\'un akrabalarına verilen krallıklar ve müttefik devletler farklı renklerle gösteriliyor. Böyle bir harita en çok hangi yılın Avrupası\'nı gösteriyor olabilir?', '1811', ['1802', '1820', '1848'], 'Napolyon\'un imparatorluk sistemi ve bağımlı krallıkları 1810-1812 arasında en geniş hâlindeydi. 1802\'de henüz imparatorluk ve kardeş krallıklar yoktu; 1820 ve 1848\'de ise Napolyon düzeni sona ermişti.'),
  ('Kıta Ablukası\'nın başarısız olmasının temel nedeni aşağıdakilerden hangisidir?', 'İngiliz donanmasının denizleri denetlemesi ve kıtanın İngiliz mallarına ihtiyaç duyması', ['İngiltere\'nin hiç ticaret yapmaması', 'Fransa\'nın abluka uygulamaktan vazgeçip İngiltere ile ittifak kurması', 'Rusya\'nın ablukaya en sıkı biçimde uyması'], 'Deniz üstünlüğü sayesinde İngiltere yeni pazarlara yöneldi; kıtadaki kaçakçılık ve müttefiklerin hoşnutsuzluğu ablukayı deldi.'),
  ('Napolyon\'un İspanya ve Rusya\'daki deneyimleri karşılaştırıldığında ortak ders hangisidir?', 'Halk direnişi ve geniş coğrafya, üstün bir orduyu bile yıpratabilir', ['Kış koşulları savaşların sonucunu hiç etkilemez', 'İşgal edilen halklar Fransız yönetimini her zaman benimser', 'Deniz gücü kara savaşlarında belirleyicidir'], 'İspanya\'da gerilla savaşı, Rusya\'da geri çekilme ve kış, büyük orduları uzun süre yıprattı ve yenilgiye götürdü.'),
  ('Viyana Kongresi\'nde Prusya\'nın bütün Saksonya\'yı, Rusya\'nın ise bütün Polonya\'yı istemesi diğer güçleri kaygılandırmıştır. Bu kaygı Kongre\'nin hangi ilkesiyle açıklanır?', 'Güç dengesi', ['Halk egemenliği', 'Ulusların kendi kaderini tayini', 'Serbest ticaret ve gümrük birliği'], 'İngiltere, Avusturya ve Fransa, bir gücün aşırı büyümesini engellemek için birleşti; sonunda Prusya Saksonya\'nın yalnız bir bölümünü aldı.'),
  ('Bir gazete 1821\'de \'Napoli\'de halk anayasa istedi, ama yabancı süngüler onu geri aldı\' diye yazıyor. Bu yorum hangi Avrupa uygulamasını eleştirmektedir?', 'Kongre sisteminin devrimlere askerî müdahalesini', ['Kıta Ablukası\'nın limanlara uygulanmasını', 'Zollverein\'i', 'Kırım Savaşı\'nı'], 'Troppau ve Laibach kararlarıyla Avusturya Napoli\'ye müdahale etti; liberaller bunu halkların iradesine karşı yabancı baskı olarak gördü.'),
  ('Aşağıdaki olaylardan hangisi Bismarck\'ın \'Fransa\'yı yalnız bırakma\' politikasıyla doğrudan ilişkilidir?', 'Rusya ile Reasürans Antlaşması\'nın imzalanması', ['Paris Komünü\'nün kurulup Thiers hükümetince bastırılması', 'Zollverein\'in kurulması', 'Kulturkampf\'ın başlatılması'], 'Bismarck, Fransa\'nın Rusya ile ittifak kurmasını engellemek için Rusya ile gizli antlaşma yaptı; diğer seçenekler iç politika ya da başka döneme aittir.'),
  ('İtalyan ve Alman birliklerinin her ikisinde de Fransa\'nın tutumu belirleyici olmuştur. Bu iki süreçte Fransa\'nın rolü arasındaki fark hangisidir?', 'İtalya\'da birliğe yardım etti, Almanya\'da ise birliğin önündeki son engel olarak yenildi', ['İki birliğe de doğrudan asker göndererek yardım etti', 'İki birliğe de hiç karışmadı', 'İtalya\'da birliğe karşı savaşıp yenildi, Almanya\'da birliği kurdu'], 'III. Napolyon 1859\'da Piyemonte ile birlikte Avusturya\'ya karşı savaştı; 1870\'te ise Prusya ile savaşıp yenildi ve güney Alman devletleri birliğe katıldı.'),
  ('1848\'de Fransa\'da genel oy getirildikten sonra köylü çoğunluğun muhafazakâr adaylara ve Louis-Napoléon\'a oy vermesi hangi sonucu ortaya koyar?', 'Genel oyun her zaman radikal sonuçlar doğurmadığını', ['Köylülerin oy kullanmadığını', 'Seçimlerin hiç yapılmadığını', 'Paris işçilerinin oyların çoğunu alıp hükümeti kurduğunu'], 'Kırsal Fransa düzen ve mülkiyet yanlısıydı; Paris\'in radikalleri seçimlerde azınlıkta kaldı. Bu deneyim muhafazakârların genel oydan korkmasını da azalttı.'),
  ('1848\'de Paris\'te bir işçi barikatlarda savaşırken \'Şubat\'ta birlikte devirdik, Haziran\'da bize ateş açtılar\' diyor. Bu işçinin anlattığı süreç hangisidir?', 'Şubat Devrimi\'nden Haziran Günleri\'ne uzanan kopuş', ['Bastille\'den Thermidor\'a uzanan süreç', 'Temmuz Devrimi\'nden Belçika ihtilaline uzanan süreç', 'Sedan\'dan Paris Komünü\'ne uzanan süreç'], 'Şubat 1848\'de monarşiyi birlikte deviren işçiler ve cumhuriyetçi burjuvazi, Haziran\'da Ulusal Atölyelerin kapatılmasıyla karşı karşıya geldi.'),
  ('Bir belgede \'Yurttaş, bugün Cumhuriyetin II. Yılı Germinal ayının 16\'sıdır\' yazmaktadır. Bu belge hangi dönemde yazılmıştır?', 'Terör döneminde, 1794 baharında', ['Napolyon\'un imparatorluğu döneminde, 1810\'da', 'Restorasyon döneminde, 1820\'de', '1789 yazında, Bastille\'den önce'], 'II. Yıl Eylül 1793-Eylül 1794 arasıdır; Germinal ise ilkbahar ayıdır (Mart-Nisan). Bu, Terör\'ün doruğuna denk gelir.'),
  ('Napolyon\'un ordularının Avrupa\'yı dolaşması sırasında bazı Alman ve İtalyan aydınların başta Fransızları alkışlayıp sonra onlara karşı çıkması nasıl açıklanabilir?', 'Önce reformcu, sonra baskıcı ve sömürücü bir güç olarak algılanmaları', ['Fransızların hiçbir değişiklik yapmamış olması', 'Aydınların Fransızcayı bilmemesi', 'Fransızların bu ülkelerden hemen çekilmesi'], 'Feodalitenin kaldırılması umut yarattı; ancak ağır vergiler, asker toplama ve yağma zamanla tepkiye dönüştü.'),
  ('1848\'de Avrupa\'nın pek çok başkentinde aynı anda ayaklanma çıkmasında aşağıdaki etkenlerden hangisinin payı en azdır?', 'Büyük bir dünya savaşının başlaması', ['1846-1847 kötü hasatları ve ekonomik bunalım', 'Liberal ve ulusçu taleplerin bastırılmış olması', 'Paris\'teki Şubat Devrimi\'nin örnek oluşturması'], '1848\'de genel bir savaş yoktu; ayaklanmaları ekonomik bunalım, siyasi baskı ve Paris\'in örneği tetikledi.'),
  ('Prusya\'nın Alman birliğini Avusturya yerine kendisinin gerçekleştirmesini kolaylaştıran ekonomik etken hangisidir?', 'Zollverein\'e önderlik etmesi ve hızlı sanayileşmesi', ['Avusturya\'nın Zollverein\'e önderlik edip gümrükleri belirlemesi', 'Prusya\'nın hiç demiryolu olmaması', 'Avusturya\'nın Ren kömür havzasına sahip olması'], 'Prusya gümrük birliğiyle Alman ekonomisini kendi çevresinde topladı; Ren ve Silezya sanayisi ona askerî ve mali güç sağladı.'),
  ('İtalyan birliğinin kuzeyden başlayıp güneye doğru tamamlanması, birlik sonrası hangi sorunun ortaya çıkmasına zemin hazırlamıştır?', 'Kuzeyin yönetimine tepki duyan yoksul güneyle uyum sorunu', ['Kuzeyin Fransa\'ya katılması', 'Güneyin sanayileşip kuzeyi geçmesi', 'Papalığın güneyi yönetmesi'], 'Piyemonte\'nin yasaları ve vergileri güneye uygulandı; güneyde eşkıyalık ve göç gibi sorunlar Mezzogiorno meselesini doğurdu.'),
  ('Fransa\'da 1789-1871 arasındaki rejim değişikliklerinin çoğunun Paris\'te başlayan ayaklanmalarla gerçekleşmesi neyi gösterir?', 'Başkentin siyasi gelişmelerde belirleyici bir ağırlığa sahip olduğunu', ['Taşranın her devrimde öncülük edip Paris\'i peşinden sürüklediğini', 'Fransa\'da başkentin önemsiz olduğunu', 'Değişimlerin hep yabancı işgalle olduğunu'], '1789, 1830, 1848 ve 1870-1871\'de Paris halkının eylemleri rejimleri devirdi; merkeziyetçi Fransa\'da Paris\'in denetimi iktidar demekti.'),
  ('1871\'de Alman İmparatorluğu\'nun Versay\'da ilan edilmesinin simgesel anlamı nedir?', 'Fransa\'nın yenilgisini ve Alman üstünlüğünü vurgulamak', ['Fransa ile dostluk kurmak', 'Versay\'ı Almanya\'nın başkenti yapmak', 'Fransız kültürüne saygı göstermek ve iki ulusu uzlaştırmak'], 'Louis XIV\'ün sarayında yapılan ilan, Fransa için ağır bir aşağılanmaydı; 1919\'da barış antlaşmasının aynı salonda imzalanması bu yüzden anlamlıdır.'),
  ('1814 Anayasa Şartı ile 1830 Temmuz Monarşisi\'nin ortak özelliği hangisidir?', 'Mülkiyete bağlı dar bir seçmen kitlesine dayanan meşruti monarşi olmaları', ['Genel oya dayanan cumhuriyet olmaları', 'Mutlak monarşi olmaları', 'Askerî diktatörlük olmaları'], 'Her iki rejimde de kral ve parlamento birlikte yönetiyordu; oy hakkı yüksek vergi ödeyen küçük bir azınlıkla sınırlıydı.'),
  ('1830\'da Fransa\'da tahta çıkan Louis-Philippe ile 1814\'te tahta çıkan XVIII. Louis arasındaki temel fark hangisidir?', 'Louis-Philippe\'in devrimle tahta çıkıp üç renkli bayrağı benimsemesi', ['XVIII. Louis\'nin cumhuriyet ilan etmesi', 'Louis-Philippe\'in Bourbon ana kolundan gelmesi', 'XVIII. Louis\'nin genel oyla seçilmesi'], 'XVIII. Louis meşruiyet ilkesiyle geri geldi; Louis-Philippe ise Orléans kolundandı, bir devrimin ürünüydü ve devrimin simgelerini kabul etti.'),
  ('1789\'da üçüncü zümre temsilcilerinin çoğunun avukat, tüccar ve memur olması devrimin ilk evresi hakkında neyi gösterir?', 'Önderliğin eğitimli burjuvazide olduğunu', ['Devrimi köylülerin doğrudan yönettiğini', 'Devrimin bir askerî darbe olduğunu', 'Soyluların meclise hiç katılmadığını ve tamamının göç ettiğini'], 'Üçüncü zümrenin temsilcileri büyük ölçüde hukukçu ve mülk sahibi burjuvalardı; devrimin ilk programı da bu kesimin taleplerini yansıttı.'),
  ('Bir tarihçi 1789-1794 arasındaki gelişmeleri \'her aşamada daha radikal bir grubun iktidarı ele geçirmesi\' diye özetliyor. Aşağıdaki sıralamalardan hangisi bu görüşe uygundur?', 'Ilımlı anayasacılar, Jirondenler, Dağlılar', ['Dağlılar, Jirondenler, Feuillant\'lar', 'Jirondenler, Feuillant\'lar, Dağlılar', 'Dağlılar, Feuillant\'lar, Jirondenler'], 'Önce anayasal monarşiyi savunan ılımlılar (Feuillant\'lar), sonra Jirondenler, en son da Robespierre\'in Dağlıları öne çıktı.'),
  ('Napolyon\'un askerî zaferlerinin pek çoğunun kısa sürede kazanılmasına karşın kalıcı bir barış sağlayamamasının temel nedeni hangisidir?', 'Her zaferin yeni bir koalisyonu doğurması ve İngiltere\'nin yenilmemesi', ['Napolyon\'un hiç antlaşma imzalamaması', 'Avrupa devletlerinin tamamının Fransa\'yla kalıcı ittifak kurması', 'Fransız ordusunun savaşlara hiç katılmaması'], 'Napolyon karada Avusturya, Prusya ve Rusya\'yı yendi; ancak İngiltere\'nin parasal desteğiyle yeni koalisyonlar kuruldu ve çatışma 1815\'e kadar sürdü.'),
  ('Viyana Kongresi\'nde Fransa\'ya ağır cezalar verilmemesinin uzun vadede yararı hangisidir?', 'Fransa\'nın intikam peşine düşmeden Avrupa düzenine katılması', ['Fransa\'nın bütün sömürgelerini kaybedip zayıflaması', 'Fransa\'nın hemen yeniden savaş açması', 'Fransa\'nın Prusya\'ya bağlanması'], 'Ilımlı barış, yenik ülkeyi kalıcı bir düşmana dönüştürmedi; 1818\'de Fransa büyük güçler arasına geri alındı.'),
  ('1830 Belçika devrimi ile 1830 Polonya ayaklanmasının sonuçları neden farklı olmuştur?', 'Belçika\'yı İngiltere ve Fransa destekledi, Polonya ise Rusya\'ya karşı yalnız kaldı', ['Polonya\'yı İngiltere destekledi, Belçika ise yalnız kaldı', 'İki ayaklanma da aynı biçimde bastırıldı', 'İki ayaklanma da bağımsızlıkla sonuçlandı'], 'Batılı güçler Belçika\'nın bağımsızlığını kabul etti; Polonya\'da ise Rus ordusu ayaklanmayı bastırdı ve dışarıdan yardım gelmedi.'),
  ('1848\'de Paris, Viyana ve Berlin\'deki devrimlerin ilk aşamada başarılı olup sonra bastırılması, devrimcilerin hangi zayıflığını gösterir?', 'Orduları kendi saflarına kalıcı olarak çekememelerini', ['Hiç halk desteği bulamamalarını', 'Devrimlerin yalnız köylerde yapılıp kentlere hiç yayılmamasını', 'Hükümdarların hiç ordu kullanmamasını'], 'Ordular sadakatini koruyunca hükümdarlar 1848 sonbaharından itibaren kentleri yeniden ele geçirdi; devrimcilerin silahlı gücü sınırlıydı.'),
  ('Carlo Alberto döneminin \'İtalya kendi başına yapacak\' (L\'Italia farà da sé) anlayışının 1848-1849\'da başarısız olması, Cavour\'un sonraki politikasını nasıl etkilemiştir?', 'Avusturya\'ya karşı büyük bir güçle ittifak aramaya yöneltmiştir', ['Birlik düşüncesinden tamamen vazgeçirmiştir', 'Papalığa bağlanmaya yöneltmiştir', 'Avusturya ile ittifak kurmaya yöneltmiştir'], '1848-1849 yenilgileri, Piyemonte\'nin Avusturya\'yı tek başına yenemeyeceğini gösterdi; Cavour bu yüzden Fransa\'nın desteğini kazanmaya çalıştı.'),
  ('Bismarck\'ın Danimarka savaşında Avusturya ile birlikte hareket edip iki yıl sonra ona savaş açması onun hangi özelliğini gösterir?', 'Koşullara göre ittifak değiştiren pragmatik tutumunu', ['Avusturya\'ya her koşulda bağlılığını', 'İdeolojik olarak liberal oluşunu ve parlamentoya bağlılığını', 'Savaştan her zaman kaçınmasını'], 'Bismarck Avusturya\'yı önce ortak, sonra rakip olarak kullandı; Schleswig-Holstein\'ın ortak yönetimi 1866 savaşının gerekçesine dönüştü.'),
  ('Ems Telgrafı olayında Bismarck\'ın davranışı hangi kavramla en iyi açıklanır?', 'Kamuoyunu yönlendirerek diplomatik kışkırtma', ['Barışçıl arabuluculuk ve uzlaştırıcı diplomasi', 'Uluslararası hukuka tam bağlılık', 'Tarafsızlık politikası'], 'Bismarck, metni kısaltıp basına vererek Fransız ve Alman kamuoyunu kızıştırdı; böylece Fransa\'yı savaş ilan etmeye itti.'),
  ('Bir öğrenci 19. yüzyılda kurulan yeni devletleri sıralıyor: Belçika, Yunanistan, İtalya, Almanya, Romanya. Bu devletlerin kuruluşunda ortak etken hangisidir?', 'Ulusçuluk ve büyük güçlerin desteği ya da onayı', ['Tümünün Fransız Devrimi\'nden önce kurulmuş olması', 'Tamamının cumhuriyet olarak doğması', 'Tamamının Osmanlı\'dan ayrılması'], 'Bu devletlerin hepsi ulusçu hareketlerin ürünüdür ve kuruluşları büyük güçlerin desteği, savaşları ya da diplomatik onayıyla mümkün olmuştur.'),
  ('1789 bildirisi \'insanlar özgür ve hakça eşit doğar\' derken Fransız sömürgelerinde köleliğin bir süre daha sürmesi neyi gösterir?', 'İlan edilen evrensel ilkelerle uygulama arasında çelişki bulunduğunu', ['Bildirinin köleliği açıkça savunduğunu', 'Sömürgelerin Fransa\'ya ait olmadığını', 'Köleliğin 1789\'dan önce kaldırıldığını'], 'Kölelik ancak 1794\'te kaldırıldı, 1802\'de geri geldi ve 1848\'de kesin olarak sona erdi; bu durum evrensel hak söylemi ile çıkarlar arasındaki gerilimi gösterir.'),
];
